import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Канон апостолу Хомі","e":"Canon to the Apostle Thomas","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Тріста́ти крі́пкия, Рожде́йся от Ді́ви, безстра́стія во глубині́ душі́ трича́стноє потопи́, молю́ся, да Тебі́, я́ко в тимпа́ні, во умерщвле́нії тілесе́ побі́дноє воспою́ пі́ніє.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Безнача́льна Си́на Бо́жия, Бо́га Сло́ва, я́вльшагося на землі́, зра́ком Су́щим по нам, Єго́же ви́діл єси́, сла́вне, Єго́же і ру́ки дла́нію, і ребро́ осяза́л єси́, умоли́ спасти́ па́ству твою́.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Зна́тель та́йних, і утро́би істязу́яй, і сердця́ іспиту́яй, Бог мой Ісу́с, тя, Фомо́ всеблаже́нне, Своєго́ Богоявле́нія служи́теля, і свиді́теля, і апо́стола Боже́ственна прия́т.","Вод та́їнственних ріка́ ти показа́лся єси́, напая́ющая, Фомо́, лице́ землі́; церко́вний же сонм струя́ми Богозна́нія і шу́мом Ду́ха многобо́жную пре́лесть отгна́л єси́.","Богородичен: Сме́рти і тлі потреби́тельниця су́щи, нетлі́нія істо́чник ро́ждшая, Христа́, Богоро́дице Всепі́тая, і безсме́ртія украси́вшаго благода́тію челові́чеськоє єстество́, Пречи́стая."]},{"h":"Пісня 3","ps":["Ірмос: Не му́дростію, і си́лою, і бога́тством хва́лимся, но Тобо́ю, О́тчею Іпоста́сною Му́дростію, Христе́: ність бо свят, па́че Тебе́, Человіколю́бче.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Доброді́телі добро́тою благолі́пен сий подо́б'яся самови́дче, і чудеси́, інді́ов злови́дноє сві́том Боже́ственним озари́в, і ві́рою просвіти́л єси́ тіх помраче́ніє.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Заре́ю разже́гся самоді́тельством Ду́ха, я́ко стріла́ Богосві́тлая, по́слан бил єси́, Богоприя́тне, і мир просвіти́л єси́, Фомо́, чудеси́.","Тайнонауче́н Боже́ственния му́дрости догма́том, я́коже ско́рость мо́лнії преходя́щия, апо́столе Фомо́, сві́том просвіти́л єси́ ми́ра конці́.","Богородичен: Неіскусобра́чная, Бо́га пло́тію ро́ждши, страсте́й прило́ги коле́блема м'я утверди́: ність бо, Пречи́стая, ра́зві Тебе́ помо́щници."]},{"h":"Сідален, глас 8","ps":["Мре́жею слове́с Боже́ственних ри́би улови́в слове́сния, сія́ прине́сл єси́ нача́ток Бо́гу на́шему, і в Христо́ви я́зви жела́я облещи́ся, подо́бник стра́сті Єго́ яви́лся єси́. Тім, соше́дшеся по до́лгу, чтим, апо́столе сла́вне, всепра́зднственную па́м'ять твою́ і согла́сно вопії́м ті: моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Богородичен: Я́ко Ді́ву і Єди́ну в жена́х, Тя, без сі́мене Ро́ждшую Бо́га пло́тію, всі ублажа́єм ро́ди челові́честії: огнь бо всели́ся в Тя Божества́ і, я́ко младе́нця, доі́ши Зижди́теля і Го́спода. Тім А́нгельський і челові́чеський род досто́йно сла́вим пресвято́є рождество́ Твоє́ і согла́сно вопіє́м Ті: моли́ Христа́ Бо́га согріше́ній оставле́ніє дарова́ти покланя́ющимся ві́рою пресвято́му рождеству́ Твоєму́."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́, во о́блаці ле́гці при́йде Ісу́с Пребоже́ственний, нетлі́нною дла́нію, і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Велича́йшим чуде́с явле́нієм наче́н і догма́тов Боже́ственних сла́ву сві́тлі ізлага́я, вселе́нную об'я́л єси́ пропові́данієм, взива́ющу: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Я́ко самови́дця тя Сло́ва і те́плаго служи́теля, і Того́ сла́ви і вели́чествія свиді́теля, і я́ко ві́рна строї́теля, і апо́стола восхваля́єм тя, блаже́нне Фомо́, всече́стне.","Я́коже неві́стний черто́г і ски́нію Небе́сную, основа́ніє на Ка́мені краєуго́льнім утверди́в, назда́л єси́, блаже́нне всеприснопа́м'ятне, зову́щим: сла́ва, Христе́, си́лі Твоє́й.","Богородичен: Зе́млю неора́нную, Клас жи́зні возді́лавшую, і о́блак ле́гкий, ту́чу, Жизнода́вця істочи́вшую, Всесвяту́ю Ді́ву імену́єм, зову́ще: сла́ва, Христе́, си́лі Твоє́й."]},{"h":"Пісня 5","ps":["Ірмос: Нечести́вії не у́зрять сла́ви Твоє́й, Христе́, но ми Тя, Єдиноро́дне, Оте́чеськия сла́ви сія́ніє Божества́, от но́щі у́тренююще, воспіва́єм Тя, Человіколю́бче.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Осія́н, апо́столе, сла́вою Христо́вою і, ребро́ животво́рноє осяза́в, поче́рпл єси́ неізсліди́мую Богосло́вія пучи́ну і мир обогати́л єси́.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Не прише́д к пе́рвому Твоєму́ вхо́ду Фома́, не ві́руя же ученико́м, ві́ровав же посліди́, ра́дуяся, возопи́, Тя, Бо́га і Го́спода возвіща́я, Многоми́лостиве.","Я́ко не́бо одушевле́нноє, сла́ву Твою́, Христе́, гро́мом духо́вним Фома́ возопи́, іспові́дуя і Бо́га, і Го́спода, Тя ві́рним благовісти́.","Богородичен: Побіди́теля покажи́, Всенепоро́чная, ум страсте́й і помишле́ній стремле́нія покори́ сих, Богоневі́сто, Бо́га Ро́ждшая, Спаси́теля душ на́ших."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися ра́ди ми́лости от ребр Твої́х істе́кшею Кро́вію.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Всіх неві́ріє, Фомо́, душегу́бноє, неві́рованіє твоє́, блаже́нне, ісціля́єть: ти бо несумні́нно гвозде́й же і копія́ я́зви іспита́л єси́. Іспусти́л єси́, я́ко си́лен, Христе́, апо́стола, я́ко стрілу́ ізощре́ну, в сердця́ враг Твої́х, Жизнода́вче, і кори́стей об'я́тіє Тебі́ сих приведе́.","Же́ртви і́дольськия, Ще́дре, упраздни́л єси́, закла́н бив на Дре́ві, і заколе́нії святи́ми Богоглаго́ливих апо́стол, подража́ющих Твоя́ страда́нія.","Богородичен: О чу́до, всіх чуде́с нові́йшеє: я́ко Ді́ва во утро́бі вся́чеськая Содержа́щаго, неіскусому́жно заче́нши, не тісновмісти́."]},{"h":"Кондак, глас 4","ps":["Прему́дрости благода́ті іспо́лнен, Христо́в апо́стол і служи́тель і́стинний в покая́нії вопія́ше Тебі́: Ти мой єси́ Бог же і Госпо́дь."]},{"h":"Ікос","ps":["Госпо́дню ученику́ і вели́кому тайнопові́дателю, Фомі́ Богоглаго́ливому, Петр возопи́: ви́діхом Го́спода. Рече́ же той: а́ще не ви́жду аз я́зви рук Єго́, не уві́рую, вопія́ше близне́ць. Тогда́ Влади́ка всіх, я́коже раб приї́де, хотя́ спасти́ вся, і глаго́леть Фомі́: осяжи́ ру́ки Моя́ і ре́бра і не не ві́руй: Аз бо єсьм Госпо́дь і Бог твой. Он же с покая́нієм возопи́: Ти мой єси́ Бог же і Госпо́дь."]},{"h":"Пісня 7","ps":["Ірмос: В пещі́ Авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че, не́жели пла́менем опаля́ємі, взива́ху: Благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","С ви́шніми ликостоя́ньми, я́ко апо́стол, ра́дуяся, лику́єши, блаже́нне, на небесі́х, воспіва́єши же, веселя́ся: Благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","От коне́ць до коне́ць протече́ твоє́ віща́ніє і глаго́л твої́х Боже́ственних предложе́ніє, зову́щия науча́ющеє: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Храм бил єси́ ти Тро́йці, прехва́льне, ті́мже і хра́ми і́дольськия і куми́ри разруши́л єси́, апо́столе, хра́ми же воздви́г во сла́ву і хвалу́ Христа́ Бо́га.","Богородичен: Зако́нния рабо́ти Твої́м Рождество́м ізба́вихомся: Ти бо, Богоро́дице, Ізба́вителя неіскусому́жно нам родила́ єси́. Благослове́нна ти в жена́х єси́, Всенепоро́чная Влади́чице."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть. Тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","С Бо́гом бесі́дуя вопло́щшимся, плоть заби́в, яви́лся єси́, блаже́нне, преми́рним же обоже́нієм обогати́лся єси́, приближе́нієм к Бо́гу Боготвори́м, і, Го́спода по́йте, зов'я́, і превозносі́те Єго́ во вся ві́ки. Любо́вію Христу́ сочета́вся, смерть с Ним, блаже́нне, возлюби́л єси́, і со апо́столом Твої́м і́дем, віща́в, і с ним смерть при́ймем: Го́спода по́йте, вопія́, і превозносі́те Єго́ во вся ві́ки.","Вас Христо́с апо́столи, о́блаки во́льнаго дождя́ показа́, ту́чами наводня́ющия Боже́ственнаго позна́нія Це́ркві, прему́дрії, і напая́ющия пою́щих: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки.","Богородичен: Поро́ков і скверн чиста́ і вся́кия святи́ні єси́ храм, Сло́во Всесвято́є, вся освяща́ющеє, Отцю́ Собезнача́льноє, породила́ єси́. Тім Тя, Ді́во, поє́м і превозно́сим во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний, от несіко́мия гори́, Тебі́, Ді́во, краєуго́льний отсіче́ся, Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім, веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Колесни́ця світоно́сная яви́лся єси́ сідя́щаго Сло́ва, на благолі́пнійшей твоє́й душі́ і Богоно́сній носи́ма, ко спасе́нію, сла́вне, направля́я пою́щих тя.","Приспів: Святи́й апо́столе Фомо́, моли́ Бо́га о нас.","Твою́ преблаже́нную па́м'ять соверша́юще, мо́лим вся́каго треволне́нія ізба́витися хода́тайством дерзнове́нія твоєго́, є́же, я́ко Христо́в апо́стол, і́маши, Богови́дче всече́стне.","Днесь па́м'ять твою́ всі, Фомо́ апо́столе, соверша́єм, освяти́ і просвіти́ ві́рою іскуше́ній, і обстоя́ній, і страсте́й вся́ких избавля́я моли́твами твої́ми.","Богородичен: Красе́н прозябе́ Клас от землі́ Діви́чеськия, Бо́жиє Сло́во, І́мже пита́ємся ві́рнії, в Не́мже і живе́м і составля́ємся. Тім Тя, Ро́ждшую, я́ко Богоро́дицю велича́єм."]},{"h":"Світилен","ps":["Самови́дче і апо́столе Христа́ Всеще́драго, мир дарова́ти всей вселе́нній і побі́ди во́їнству на́шему, і прегріше́ній оставле́ніє, і спасе́ніє іспроси́ тя, Фомо́, восхваля́ющим я́ко ученика́ Богоглаго́лива.","Я́ко со́лнце восто́ка, інді́ом посла́ся, Фомо́ апо́столе, пресві́тлоє, апо́столов сла́во, і тіх омраче́ніє сві́том слове́с твої́х і Тро́йчеською ві́рою просвіти́л єси́. Тім святу́ю твою́ і Боже́ственную пра́зднуєм па́м'ять.","Богородичен: Моле́бницю Ті приво́дим і те́плую Засту́пницю, Пречи́стую Ма́тер Твою́, ві́рнії по до́лгу: сподо́би раби́ Твоя́ причасти́тися сла́ви Твоєя́, Христе́, і пра́ведних наслі́дія, і пи́щі ра́йськия, і даждь Ца́рство Небе́сноє."]}],"notes":[]},{"u":"Канон апостолу Якову Алфеєву","e":"Canon to the Apostle James, son of Alphaeus","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Ру́ку мі даждь, Богови́дче і учениче́ Христо́в, Іа́кове, честни́й твой пра́здник похвали́ти устреми́вшуся, і світ се́рдцю моєму́ твої́ми моли́твами возсія́й.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Струя́ми Боже́ственния му́дрости напоє́н, ріка́ істе́кл єси́ от рая́ сла́дости і земно́є лице́ тече́ньми благоче́стія і́стинно я́ві напої́л єси́.","Свяще́ннійшему ли́ку учени́ко Христо́вих счета́лся єси́, Іа́кове, ісполня́я число́ двонадеся́тних; с ни́миже, Влади́ці предстоя́, нас помина́й.","Богородичен: Тя, Пречи́стая Ді́во, не́бо простри́й Госпо́дь і зе́млю основа́вий, не́бо земно́є нам яви́л єсть, із Тебе́ проше́д пло́тію."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Боже́ственнаго Ду́ха я́ві приє́м зарю́, во тьмі су́щим, я́ко у́тро, показа́лся єси́ сві́тло, Со́лнця ми́сленнаго возвіща́я всім явле́ніє.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Нога́ твоя́ ста я́вственно в пра́вости, блаже́нне, у Царя́ Пра́ваго же і Блага́го, лику́ющи боголі́пно і ше́ствующи стезю́ Небе́сную.","Си́на Безнача́льна Бо́жия, вся творя́щаго Боже́ственною вла́стію, неле́стна Тайноучи́теля, зна́нія і́стини тя науча́юща, імі́л єси́, Іа́кове.","Богородичен: Марі́є, всіх наде́ждо на Тя наді́ющихся, ро́ждши Сло́во, воплоще́нноє нас ра́ди, разли́чних м'я напа́стей і бід, Пречи́стая, ізба́ви."]},{"h":"Сідален, глас 8","ps":["Му́дрость і́стинно учи́теля імі́в, тя науча́ющую су́щим па́че ума́, му́дрость об'юро́дил єси́ є́ллинськую, богодухнове́нне; і язи́ком бил єси́ світи́льник Боже́ственний, благоче́стія словеси́ направля́я безу́мния. Тім ізба́вленнії тобо́ю от пре́лести, досто́йно поє́м тя і ві́рно ублажа́єм, богоглаго́ливе Іа́кове: моли́ Христа́ Бо́га гріхо́в оставле́ніє пода́ти чту́щим любо́вію святу́ю па́м'ять твою́.","Богородичен: Со́лнця о́блаче разу́мнаго, Боже́ственнаго Сві́та Світи́льниче златокова́нний, Нескве́рная, Небла́зная, Всенепоро́чная Влади́чице, омраче́нную ду́шу мою́ осліпле́нієм страсте́й безстра́стія заре́ю просвіти́, молю́ся; і оскверне́нноє моє́ се́рдце оми́й пото́ки умиле́нія, покая́нія же слеза́ми, і от тимі́нія м'я очи́сти діл мої́х, да любо́вію зову́ Ті: Богоро́дице Присноді́во, моли́ Христа́ Бо́га прегріше́ній оставле́ніє пода́ти мі, Тебі́ бо імі́ю наде́жду, раб Твой."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, Честна́я Це́рков боголі́пно поє́ть, взива́ющи от сми́сла чи́ста о Го́споді пра́зднующи.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Сам тя Госпо́дь Єди́н Святи́й честно́му ли́ку ученико́в, блаже́нне, сочета́, честно́є і сві́тлоє житія́ твоєго́ прови́дівий.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Чуде́с іспо́лнен Боже́ственнаго Ду́ха бив, богопропові́дниче, чудотвори́ши бо, неду́ги отгоня́я, і лука́вства духо́в челові́ки свободи́л єси́.","Боже́ственноє сія́ніє, наше́дшеє се́рдцю твоєму́, блаже́нне, богосві́тло сіє́ соді́ла і прия́тно па́че ума́ дарова́ній сотвори́.","Богородичен: Боже́ственним Твої́м Рождество́м, Ді́во Всечи́стая, а́нгельстії чи́ни і земни́х собо́ри совокупи́шася; Миронача́льника бо Христа́ і Спа́са всіх родила́ єси́."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті ду́ші любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, І́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Со́лнцю, блаже́нне, у́мному собесі́дник бив, лучи́ ти отту́ду приє́мля, є́же по существу́ пе́рвий Той єсть, втори́й по благода́ті бил єси́, сла́вне.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Ум чисті́йший імі́в, сві́тло же і чи́сто се́рдце ти стяжа́в, вопло́щшагося Бо́га ви́діл єси́, непостижи́маго ра́зумом.","Уступа́єть ті, учениче́, вся́ко проро́чество, і вся́ко законоположе́ніє, пребога́те; ті́ми бо дре́вле Пропові́даємаго самови́дно сподо́бился єси́, блаже́нне, ви́діти.","Богородичен: Се, Ді́во, проро́чеськи імі́ла єси́ во чре́ві Твоє́м, Су́щаго над всі́ми Влади́ку і Го́спода, і неізрече́нно Сего́, Чи́стая, родила́ єси́, Ді́во, по Рождестві́ нетлі́нна преби́вши."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре, воздвиза́ємоє зря напа́стей бу́рею, к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: возведи́ от тлі живо́т мой, Многоми́лостиве.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Но́ги твоя́ кра́сния мир неле́стно я́ко благовіству́юще, мир су́що преєсте́ственний, і ум преіму́щий, учениче́ Христо́во всече́стне.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Разумі́ти та́їнство і пропові́дати стра́шноє Бо́жия воплоще́нія сподо́бился єси́, Іа́кове, перводі́льния лучи́ приє́мий от Самаго́ Височа́йшаго, приснопа́м'ятне.","Неізрече́ннаго сві́та сія́я сві́тлостьми досто́йно, верхо́вний Христо́в апо́столе, прилі́жно моли́ся о творя́щих па́м'ять твою́, сла́вне, пречестну́ю.","Богородичен: Всі́ми влади́чествующа тва́рми я́ко Бо́га Блага́го ро́ждши, согріше́ній мої́х, Пречи́стая, стру́пи до конця́ потреби́, благоутро́бна содіва́ющи Ро́ждшагося із Тебе́."]},{"h":"Кондак, глас 2","ps":["Тве́рдо му́дрості догма́ти в ду́ші благочести́вих вложи́вшаго похвала́ми да ублажи́м я́ко Боговіща́теля всі Іа́кова: Престо́лу бо сла́ви Влади́чню предстоя́ і со всі́ми А́нгели ра́дується, моля́ непреста́нно о всіх нас."]},{"h":"Ікос","ps":["Я́ко учени́ко Христо́в і друг Невеще́ственним лико́м спребива́яй при́сно, і, Сві́том озаря́єм невече́рняго світодая́нія, ума́ моєго́ тьму разріши́, всеблаже́нне: я́ко да твою́ світоно́сную па́м'ять воспою́, ю́же поє́ть вся твар, благоче́стно пра́зднующи днесь; всіх бо ві́рних наста́вник і світи́льник бил єси́, Іа́кове, моля́ непреста́нно о всіх нас."]},{"h":"Пісня 7","ps":["Ірмос: О́троци во Вавило́ні, пе́щнаго пла́мене не убоя́шася, но посреді́ пла́мене вве́ржені, ороша́ємі, поя́ху: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Сві́тлостьми і сія́ньми Ду́ха просвіще́ннаго, язи́к мно́жество сі́м'я Боже́ственноє тя імену́єть, зову́ще: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Му́дростію укра́шен богодарова́нною ті разори́л єси́ мирську́ю му́дрость, богому́дренно зови́й, апо́столе: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Во всю зе́млю ізи́де віща́ніє твоє́, апо́столе Іа́кове, є́же возвісти́л єси́, я́ко гром, всім страна́м, прему́дре, Воплоще́нноє Сло́во досто́йно пропові́дая.","Богородичен: Святи́х святі́йши, Ді́во Ма́ти, Ти била́ єси́, я́ко ро́ждши Бо́га несказа́нно, Єго́же воспіва́юще, непреста́нно зове́м: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: За зако́ни оте́чеськия блаже́ннії во Вавило́ні ю́ноши, предбі́дствующе, царю́ющаго оплева́ша повелі́ніє безу́мноє і, совоку́плени і́мже, не свари́шася огне́м, Держа́вствующему досто́йную воспіва́ху піснь: Го́спода по́йте діла́ і превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Священноучени́к, Небе́сним науче́н і́стинно, блаже́нне, та́їнством, проше́л єси́ всю вселе́нную, апо́столе, пропові́дая велегла́сно сло́во ві́ри Христо́ви і науча́я неізрече́нною благода́тію: Го́спода воспіва́йте діла́ і превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Бога́ть бил єси́ і блаже́н, сподо́блен вся́каго блаже́нства, я́ко собесі́дник і сообита́тель бив Влади́ці, і коне́чноє і́стинно жре́бієм до́брі обога́щся, і Сло́ву, свеселя́ся, воспіва́ше: Го́спода по́йте діла́ і превозносі́те во вся ві́ки.","За мир моли́твенник ізя́щнійший ко Спа́су ста́ни, блаже́нне апо́столе, прося́ сви́ше бога́тнаго ми́ра Це́рквам, і хва́лящим тя ві́рно прегріше́ній оставле́ніє, і душа́м спасе́ніє, вопію́щим: Го́спода по́йте діла́ і превозносі́те во вся ві́ки.","Богородичен: Ти спасе́нія всім Хода́тайця, Богома́ти, яви́лася єси́, Єди́на Всепі́тая, Спа́са ро́ждши Бо́жия, Бо́га Сло́ва, ізба́вльшаго нас дре́внія кля́тви і благослове́ніє дарова́вшаго ві́рою зову́щим: Го́спода по́йте діла́ і превозносі́те во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Не рида́й Мене́, Ма́ти, зря́щи во гро́бі, Єго́же во чре́ві без сі́мене зачала́ єси́, Си́на: воста́ну бо, і просла́влюся, і вознесу́ со сла́вою непреста́нно я́ко Бог ві́рою і любо́вію Тя велича́ющия.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Яви́лся єси́ ми́ру, я́коже мо́лнія претека́я, во тьмі дре́вле і сі́ні неві́дінія сідя́щия, влеки́й ко Сві́ту незаходи́мому Вопло́щшагося Єдиноро́днаго Си́на, Єго́же самови́дець і ді́йственний слуга́ бил єси́, блаже́нне; Єго́же велича́єм.","Приспів: Святи́й апо́столе Іа́кове, моли́ Бо́га о нас.","Бу́рноє, блаже́нне, от небесе́ носи́моє диха́ніє приє́м і язи́ком огнедохнове́нним обога́щся, пожига́єши, я́ко те́рніє, безбо́жную мирську́ю му́дрость, свіща́тельними заря́ми пропові́данія Христо́ва сія́я і мрак разоря́я, Богоблаже́нне.","Прийми́, Богогла́се апо́столе Іа́кове, моле́бную піснь, ю́же ті прино́сим, твою́ пра́зднующе пречестну́ю і пресві́тлую па́м'ять; ізба́ви от гріхо́в раби́ твоя́, верхо́вний Христо́в апо́столе, прилі́жно моля́ся, да досто́йно тя велича́єм.","Богородичен: Я́ко неіскусому́жно во чре́ві Твоє́м приє́мши Сло́во, пребила́ єси́ Нетлі́нна, Пречи́стая Ді́во, і ро́ждши нам Емману́їла, су́щаго вку́пі Бо́га і Челові́ка. Сего́ сугу́ба єстество́м ві́дуще, Тя велича́єм."]},{"h":"Світилен","ps":["Не я́ко си́на Алфе́єва, но я́ко ученика́ Сло́ва, разумі́єм тя, Іа́кове, апо́столов сла́во: і́бо Боже́ственноє сія́ніє я́вственно прия́л єси́ і благода́ть чуде́с отгоня́ти неду́ги от челові́к, ві́рою соверша́ющих всесвяще́нную па́м'ять твою́.","Богородичен: Я́ко іму́щи благоутро́біє і ми́лость вели́кую, Богоро́дице Ді́во, при́зри, Пренепоро́чная, на моє́ смире́ніє і стра́стную бу́рю і печа́лей нахожде́ніє разжени́, Чи́стая, і огня́ геє́нськаго ізба́ви м'я Твої́ми моли́твами."]}],"notes":[]},{"u":"Канон святителю Афанасію, єпископу Ковровському","e":"Canon to St Athanasius, Bishop of Kovrov","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́ня погрузи́, чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в, і разділи́в мо́ре, Ізра́їля же біглеця́, пішехо́дця спасе́, піснь Бо́гові воспіва́юща.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Прийми́ пі́ніє і хвале́ніє на́ше, святи́телю Афана́сіє, ти бо, поноше́нія і ра́ни, заточе́ніє і ізгна́ніє, і го́ркия рабо́ти Христа́ ра́ди претерпі́в, в Ца́рствіє Небе́сноє вшел єси́, іді́же о нас мо́лиши і взива́єши: Україно Святая, храни ві́ру правосла́вную, в не́йже тебі́ утвержде́ніє.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Ре́вностію по Бо́зі распала́єм, святи́телю Афана́сіє, мо́ре неві́рія і злоче́стія проше́л єси́ і землі́ обетова́нния, рая́ сла́дости, дости́гл єси́, іді́же со всі́ми святи́ми землі́ Українськия взива́єши: Україно Святая, храни ві́ру правосла́вную, в не́йже тебі́ утвержде́ніє.","Єгда́ даде́ся ті, святи́телю, благода́ть, не то́чію во Христа́ правосла́вно ві́ровати, но і по Нем страда́ти і Єго́ іспові́дати, о́браз ві́рним синово́м Українським яви́л єси́, взива́я: Україно Святая, храни ві́ру правосла́вную, в не́йже тебі́ утвержде́ніє.","Богородичен: Тебі́, Пречи́стая Ді́во, возопи́ Арха́нгел: благослове́н Плод чре́ва Твоєго́, Богоневі́сто, ті́мже і ми, раби́ Твої́, я́ко і́стинную Богома́тер, правосла́вно Тя велича́єм."]},{"h":"Пісня 3","ps":["Ірмос: Утвержде́й на ка́мені ві́ри, на сем сози́жду Мою́ Це́рков, реки́й, Го́споди, спаси́ м'я, вопію́ща: Ти єси́, Христе́, Син Бо́га Жива́го, і в Тебі́ утверди́ся дух мой.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Єгда́ отсту́пници нечести́вії воста́ша на Го́спода і на святи́х Єго́, тогда́ ти, богому́дре Афана́сіє, нело́жно уча́ше, ка́ко подоба́єть в дому́ Бо́жії жи́ти, я́же єсть Це́рков Бо́га Жи́ва, столп і утвержде́ніє і́стини.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Реко́ша отсту́пници в безу́мії своє́м: ність Бог, прийді́те і отста́вим вся пра́здники Бо́жия от землі́ Українськия. Ти же, святи́телю Афана́сіє, лю́дем поколеба́вшимся вопія́л єси́: Україно Святая, храни ві́ру правосла́вную, в не́йже тебі́ утвержде́ніє.","Повеліва́л єси́ апо́стольськи ві́рним, Афана́сіє богодухнове́нне, отлуча́тися вся́каго бра́та, безчи́нно ходя́ща, а не по преда́нію, і благода́тію утвержда́ти сердца́.","Богородичен: Єди́на пло́тію Бо́га ро́ждшая, мо́лимся Ті, Чи́стая: ізба́ви сіте́й вра́жиїх ду́ші на́ша і утверди́ на ка́мені Боже́ственних за́повідей, я́ко на Тя упова́ніє возложи́хом."]},{"h":"Сідален, глас 4","ps":["Взира́я на Нача́льника ві́ри і Соверши́теля Ісу́са, святи́телю о́тче Афана́сіє, благода́тію не́мощ єстества́ челові́чеськаго превозмо́гл єси́: в го́рких рабо́тах мно́жає, в ра́нах пребо́лі, в темни́цях і́злиха, близ сме́рти мно́гащи, во ізгна́нії надо́лзі пребива́я, біди́ от гони́телей, біди́ от лжебра́тії безро́потно терпі́л єси́ і пра́вду яви́л єси́. Ті́мже жи́зні ві́чния ни́ні наслажда́єшися.","Богородичен: Днесь сві́тло красу́ється сла́внійший град Влади́мир, ра́достно соверша́я, Влади́чице, пра́здник явле́нія Твоєго́ святи́телю Макси́му, єго́же ни́ні воспомина́юще і моля́щеся Тебі́, взива́єм си́це: о, Пречу́дная Влади́чице Богоро́дице, моли́ся Преві́чному Архієре́ю – Си́ну Твоєму́, да Це́рков Правосла́вную непоколеби́му утверди́ть, град сто́льний Влади́мир і всю зе́млю Українськую в ми́рі сохрани́ть і спасе́ть в правові́рії ду́ші на́ша."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й Сла́ва, Человіколю́бче.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Вся́кая печа́ль упраздня́ється моле́бними пі́нії твої́ми, святи́телю Афана́сіє, сло́во бо твоє́, благода́тію іспо́лненноє, воздвиза́єть вся сла́вити Єди́наго Человіколю́бця.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Іспові́дал єси́ Го́спода пред отсту́пники і гони́телі, со проро́ком взива́я: с на́ми Бог, разумі́йте і покаря́йтеся, стра́ха же ва́шего не убої́мся, ніже́ смуті́мся, Го́спода же Бо́га на́шего Того́ святи́м, Єди́наго Человіколю́бця.","І да́же до ста́рости не оста́ви тя Госпо́дь, святи́телю Афана́сіє, до́ндеже ми́шцю Єго́ ро́ду гряду́щему возвісти́л єси́, наставля́я: я́ко а́ще не Госпо́дь помо́гл би нам, не пом'яну́лося би і́м'я України Святия ктому́, ни́ні же прославля́єм Єди́наго Человіколю́бця.","Богородичен: Добро́ту Іа́ковлю, Ю́же возлюби́, Пребезнача́льноє Сло́во от ві́ка ізбра́ і, всели́вся в Ню, обнови́ челові́чеськоє єстество́. Ті́мже прославля́єм Єго́, Єди́наго Человіколю́бця."]},{"h":"Пісня 5","ps":["Ірмос: Я́ко Бо́га іно́го, Бла́же, па́че Тебе́, не зна́єм, к Тебі́, Сві́ту Незаходи́мому, от но́щі у́тренююще, воспіва́єм Тя, Человіколю́бче.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","От па́стви разлуче́н бив, святи́телю, Христа́ іспові́дал єси́ во ізгна́нії, ті́мже пра́вило ві́ри і о́браз благоче́стія бли́жнім і да́льним показа́л єси́, прославля́я Го́спода Человіколю́бця.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Круг богослуже́бний по вся дні ісполня́я, святи́телю Афана́сіє, уста́в церко́вний ві́рним із'ясни́л єси́, науча́я лю́ди воспіва́ти Го́спода Человіколю́бця.","От лю́тия сме́рті ізба́ви тя Бог, да возмо́жеши утіша́ти су́щия в ско́рбіх і печа́ліх, науча́я ти́я прославля́ти Помо́щника і Покрови́теля, Го́спода Человіколю́бця.","Богородичен: Напра́ви м'я к покая́нію, Не́бо У́мноє, Со́лнце пра́вди нам возсія́вшеє, я́ко да узрю́ світ спасе́нія, Влади́чице Чи́стая, і просла́влю Го́спода Человіколю́бця."]},{"h":"Пісня 6","ps":["Ірмос: Іо́ну в ки́ті, Го́споди, єди́наго всели́л єси́, мене́ же, свя́заннаго мре́жами вра́жіями, я́ко от тлі о́наго спаси́.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Це́рков Українськая воспіва́єть по́двиги твоя́, святи́телю Афана́сіє, ти бо, заби́в жите́йськая і небре́г тіле́сная жи́зні ра́ди бу́дущия, тоя́ наслі́дник яви́лся єси́ і ни́ні мо́лишися о душа́х на́ших.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","А́ще і обурева́ємі гоне́нії безбо́жними би́ша лю́діє ві́рнії, оба́че словеси́ твої́ми на спасе́нія стезі́ упра́вил єси́ ти́я, о́тче Афана́сіє богоглаго́ливе.","Текл єси́ ті́сним путе́м, ра́дуяся, Афана́сіє великоімени́те, пі́сні твоя́ со слеза́ми покая́нія і іспові́данія, я́ко же́ртву благоприя́тную, Бо́гу принося́.","Богородичен: Освяти́ ум мой і просвіти́ се́рдце моє́, Пресвята́я Ма́ти Бо́жия, і обдержа́щих м'я зол ізба́ви, христия́н Засту́пнице."]},{"h":"Кондак, глас 3","ps":["Днесь Афана́сій святи́тель, Христо́в іспові́дник і пра́ведник, в невече́рнім Ца́рстві Сла́ви сві́тло лику́єть і в со́нмі всіх Українських святи́х, всесоста́вним гла́сом побі́дную піснь воспіва́я, прилі́жно мо́лить о нас Преві́чнаго Трієди́наго Бо́га."]},{"h":"Ікос","ps":["Днесь, ві́рнії, соше́дшеся, восхва́лим святи́теля Афана́сія, безсме́ртія тезоімени́таго, ревни́теля Правосла́вія, блюсти́теля благоче́стія, обличи́теля отсту́пников, пропові́дника покая́нія, піснопі́нії досточу́дними святи́х, в землі́ Українській просія́вших, просла́вльшаго, той бо прилі́жно мо́лить о нас Преві́чнаго Трієди́наго Бо́га."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снизхожде́нія огнь устиді́ся во Вавило́ні іногда́. Сего́ ра́ди о́троци в пещі́, ра́дованною ного́ю, я́ко во цві́тниці, лику́юще, поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Імі́я щит ві́ри правосла́вния, стрі́ли разжже́нния мучи́телей отража́л єси́, со проро́ком вопія́: а́ще бо па́ки возмо́жете, і па́ки побіжде́ні бу́дете, аз же воспою́: благослове́н Бог оте́ць на́ших.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Со беззако́нними вміни́вся, кротча́йший о́тче, путе́м нечести́вих нікогда́же ходи́л єси́ і ненави́дим Го́спода ра́ди бил єси́, оба́че малоду́шіє і ро́пот не поколеба́ се́рдце твоє́. Ті́мже любо́вію воспіва́л єси́ Бо́га оте́ць на́ших.","Поко́я не імі́л єси́, мно́гими содержи́м напа́стьми і во узи́лищі пребива́я, я́ко во рву льви́ном, но, наді́яся на Бо́га, возставля́ющаго ме́ртвия, взива́л єси́: благослове́н Бог оте́ць на́ших.","Богородичен: А́гнця зря́щи воздвиза́єма на Дре́ві непра́ведні, Непоро́чная А́гниця, ма́терськи слезя́щи, долготерпі́ніє воспіва́ше Си́на Своєго́ і Бо́га оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: Нече́стія орга́ни іну́ю піснь, благоче́стія же боговіща́ннії поя́ху гу́сли: благослові́те, діла́ Госпо́дня, Христа́ во ві́ки.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Си́лою благода́тною Ца́рствіє Бо́жиє бли́жнім і да́льним благовіствова́л єси́, святи́телю Афана́сіє, да іспові́дають лю́діє українськії Го́спода во ві́ки.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Єде́мом сві́тлим узи́лище мра́чноє соді́лав, ре́ку боже́ственних піснопі́ній істочи́л єси́, ієра́рше богоглаго́ливий, да почерпа́ють лю́діє українськії весе́ліє духо́вноє і благослов'я́ть Го́спода во ві́ки.","Но́вий іспові́дник Це́ркве Правосла́вния, святи́телю Афана́сіє, і оби́тель Ду́ха Свята́го яви́лся єси́, Єго́же со Отце́м і Си́ном воспіва́єши во ві́ки.","Богородичен: Безсме́ртнаго Бо́га ро́ждшая, тече́ніє сме́ртноє укроти́ла єси́, ті́мже умертви́, Чи́стая, стра́сті тілесе́ моєго́, да Тя сла́влю во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Благослове́н Госпо́дь, Бог Ізра́їлев, воздви́гнувий рог спасе́нія нам в дому́ Дави́дові, о́трока Своєго́, в ни́хже посіти́ нас Восто́к с висоти́ і напра́вил ни єсть на путь ми́ра.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Умо́м твої́м Го́рняя созерца́я, терпіливоду́шне Афана́сіє, в страда́ніїх Бо́га, я́ко Помо́щника і Покрови́теля, призива́л єси́: Твой єсьм аз, спаси́ м'я, і напра́ви на путь ми́рен.","Приспів: Святи́телю о́тче Афана́сіє, моли́ Бо́га о нас.","Де́нно і но́щно теплі́йшия моли́тви твори́л єси́, святи́телю Афана́сіє, єгда́ іноплеме́нници го́рдії гріх ра́ди на́ших на Україну ополчишася, ти же, свя́тче, вопія́л єси́: пощади́, пощади́, Го́споди, Оте́чество на́ше і напра́ви мир весь на путь ми́рен.","Єли́ко суди́ Госпо́дь мі́ру дній житія́ твоєго́, благоче́стно іспо́лнил єси́, святи́телю Афана́сіє. Ни́ні же, предстоя́ Престо́лу Вседержи́теля, мо́лиши Єго́, да напра́вить лю́ди Своя́ на путь ми́ра.","Богородичен: Тя ві́рою і любо́вію воспіва́ющія просвіти́, Всенепоро́чная Влади́чице, і тьми кромі́шния ізми́ моли́твенним предста́тельством к Си́ну Твоєму́ і Бо́гу на́шему."]},{"h":"Світилен","ps":["Предста́вил єси́ себе́ же́ртву жи́ву Бо́гові, свя́ту, благоуго́дну і непоро́чну в слове́снім служе́нії і іспові́данії, святи́телю Христо́в Афана́сіє, і та́ко просвіти́ся світ твой пред челові́ки, я́ко сла́в'ять ви́ну о тебі́ Отця́ Небе́снаго.","Слава: Печа́льнику землі́ Українськия преподо́бному Се́ргію тезоімени́ть сий, от ю́ности того́ возлюби́л єси́, свя́те Афана́сіє, і той, я́ко второ́є со́лнце, житіє́ твоє́ озаря́ше, с ни́мже ку́пно моли́ Трієди́наго Бо́га о спасе́нії душ на́ших.","Богородичен: Світ Незаходи́мий ми́ру ро́ждшая, сві́тлості святи́х сподо́би лю́ди землі́ Українськия, Тебі́ почита́ющия, і благодаре́ніє от душі́ принося́щия і вопію́щия: не забу́ди раби́ Твоя́, Єди́на Благослове́нная."]}],"notes":[]},{"u":"Канон апостолу і євангелісту Луці","e":"Canon to the Apostle and Evangelist Luke","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Піснь возсле́м, лю́діє, Чу́дному Бо́гу на́шему, свободи́вшему Ізра́їля от рабо́ти, піснь побі́дную пою́ще і вопію́ще, пої́м Тебі́ Єди́ному Влади́ці.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Колесни́ця Бо́жия пресві́тлая бил єси́, Всесвято́є нося́ І́м'я пред челові́ки, Луко́ всече́стне, колесни́ци і тріста́ти пре́лести погружа́я крі́пко.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Струю́ приї́м жи́зні: зно́єм ізсиха́ємий безбо́жия напої́л єси́ мир, Луко́ всеблаже́нне, ту́чами Богоразу́мія, із чре́ва твоєго́ ізска́чущими.","Блиста́нієм Ду́ха, Луко́, і житія́ чистото́ю озаря́єм, я́ко мо́лнія, треблаже́нне, Богода́нно сія́л єси́ всей вселе́нній, просвіща́я ві́рних сердця́.","Богородичен: Ра́дуйся, всесвяти́й хра́мі, руно́ Богоро́сноє, запеча́танний істо́чниче безсме́ртния Струї́: ста́до Твоє́, Влади́чице, сохраня́й от всіх ра́тних непліни́мо."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят я́ко Госпо́дь, і ність пра́веден я́ко Бог наш, Єго́же поє́ть вся твар: ність пра́веден па́че Тебі́, Го́споди.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Возсія́в я́ко со́лнце пропові́данієм, Це́ркве укра́сил єси́, Луко́, утвержде́ніє, пре́лести мглу теплото́ю ві́ри іста́їв, всеблаже́нне.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Скрижа́ли ізсі́кл єси́ Боголі́пния от ка́мене, пребога́те, Бо́жия воплоще́нія, оско́рд імі́я Боже́ственний язи́к твой, і уста́ Богодохнове́нная.","Во о́блак всесві́тлий входя́й, і о́блаком покрива́єм, прия́л єси́, прему́дре, Но́вий Зако́н, пе́рстом Ду́ха пи́санний на се́рдці твоє́м.","Богородичен: Ність непоро́чния я́ко Ти, Влади́чице, і ність пречи́сти па́че Тебе́, Всенепоро́чная: во чре́ві бо Бо́га Сло́ва вмісти́ла єси́, Єди́наго Многоми́лостиваго."]},{"h":"Сідален, глас 8","ps":["Я́ко соше́ственник Па́влов яви́вся, разли́чния біди́ терпіли́вні претерпі́л єси́, всехва́льне Госпо́день апо́столе, і тече́ніє страда́нієм соверши́во ві́ри, с ним во ви́шніх весели́шися, блаже́нне. Тім і ми́ру Христо́во Єва́нгеліє пропові́дав, просвіти́л єси́ подсо́лнечную всю, Луко́ всече́стне. Моли́ Христа́ Бо́га, гріхо́в составле́ніє пода́ти, пра́зднующим любо́вію святу́ю па́м'ять твою́.","Богородичен: Со́лнця о́блаче разу́мнаго, Боже́ственнаго Сві́та світи́льниче златокова́нний, Нескве́рная, Небла́зная, Всенепоро́чная Влади́чице, омраче́нную ду́шу мою́ осліпле́нієм страсте́й, безстра́стія заре́ю просвіти́, молю́ся, і оскверне́нноє моє́ се́рдце оми́й пото́ки умиле́нія, покая́нія же слеза́ми, і от тимі́нія м'я очи́сти діл мої́х да любо́вію зову́ ті: Богоро́дице Присноді́во, моли́ Христа́ Бо́га прегріше́ній оставле́ніє пода́ти мі, Тебі́ бо імі́ю наде́жду раб Твой."]},{"h":"Пісня 4","ps":["Ірмос: Із гори́ приосіне́нния, Сло́ве, проро́к, Єди́ния Богоро́диці, хотя́ща воплоти́тися, Богови́дно усмотри́, і со стра́хом славосло́в'яше си́лу Твою́.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Мо́ре язи́ков смути́л єси́, Богому́дре, конь бив Всецаря́, сла́вноє неві́рствіє со́лію Боже́ственною ослажда́я, присносла́вне.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Лук Христо́с напря́г, пусти́ стрілу́ тя, Луко́, сві́тло обощре́ну, луча́ми сія́юща благоче́стія, і просвіща́юща на́ша ду́ші.","Стра́сті душ ку́пно і тіле́с твої́х півце́в уврачи́, всеблаже́нне, та́їнственним рукоді́ланієм, гріха́ гни́лость ізрі́зуя, всему́дре.","Богородичен: Неві́сто Бо́жия, Марі́є Богороди́тельнице, ізба́ви м'я лю́тих прегріше́ній і бід, і к тишини́ приста́нищу і спасе́нія твої́ми моли́твами напра́ви."]},{"h":"Пісня 5","ps":["Ірмос: У́тренююще, вопіє́м Ті, Го́споди, спаси́ ни: Ти бо єси́ Бог наш, ра́зві Тебе́ іно́го не ві́ми.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Я́ко роса́ с Небе́с спа́дающи яви́лся єси́, пре́лести зной разоря́я словеси́ твої́ми.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Страх во чре́ві твоє́м Боже́ственний заче́н, спасе́ніє породи́л єси́ заблу́ждшим, апо́столе.","На го́ру возше́д, всеблаже́нне, доброді́телей, всім Єва́нгеліє Ца́рствія пропові́дал єси́.","Богородичен: Марі́є Богоро́дице Безневі́стная, наде́жди враго́в су́єтни сотвори́, і пою́щия Тя возвесели́."]},{"h":"Пісня 6","ps":["Ірмос: Ри́зу мні пода́ждь сві́тлу, одія́йся сві́том я́ко ри́зою, многоми́лостиве Христе́ Бо́же наш.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Му́дрости ча́шу іспи́в, напої́л єси́ всіх позна́нія Спа́са Христа́, Луко́ всему́дре.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Па́влу соісхо́дник ізбра́вся, Луко́ всеблаже́нне, язи́ки улови́л єси́ мре́жею, Богоглаго́льниче, догма́тов твої́х.","О́блак, ту́чу жи́зні нам одождя́ющ, яви́лся єси́ апо́столе, от істо́чник спасе́нія істека́ющую.","Богородичен: Куми́ров Разруши́тель, я́ко Бог, би́вшеє Рождество́ Твоє́, Марі́є Богоневі́сто, покланя́ємо єсть со Отце́м і Ду́хом."]},{"h":"Кондак, глас 2","ps":["І́стиннаго благоче́стія пропові́дника, і та́їн неізрече́нних ри́тора, звізду́ церко́вную, Луку́ Боже́ственнаго восхва́лим: Сло́во бо єго́ ізбра́, с Па́влом му́дрим язи́ков учи́теля, Єди́н ві́дий серде́чная."]},{"h":"Ікос","ps":["Зна́нієм обогати́вся го́рнійшим от руки́ Влади́чни, вруче́н бил єси́ язи́ков жребіоїму́ществу всехва́льне. Тім житіє́ распали́в Сло́вом, страна́м законополо́жник, Луко́, яви́лся єси́ па́че Моїсе́я: пе́рстом Бо́жиїм, я́ко скрижа́ли Богоначерта́нния, тобо́ю сложи́вшася Ду́хом, Боже́ственную уясни́л єси́ ві́ру. Тім і Христо́с тя просла́ви, Єди́н ві́дий серде́чная."]},{"h":"Пісня 7","ps":["Ірмос: О́троци благочести́вії во Вавило́ні о́бразу злато́му не поклони́шася, но посреді́ пещі́ о́гненния ороша́ємі, піснь воспіва́ху глаго́люще: превозноси́мий отце́в і нас Бо́же, благослове́н єси́.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Учени́к неізрече́нних та́їн Христа́ Бо́га ві́рен бив, Єва́нгеліє Сего́ Боже́ственноє пропові́дал єси́ ві́рним, всему́дре, глаго́лющим: превозноси́мий отце́в і нас Бо́же, благослове́н єси́.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Утворе́нії доброді́телей укра́шен яви́лся єси́, Луко́ всеблаже́нне, Боже́ственнаго благолі́пія заря́ми просвіща́єм, і вопія́ непреста́нно Творцю́ твоєму́: превозноси́мий отце́в і нас Бо́же, благослове́н єси́.","Іспуща́я світоно́сния лучи́, я́коже в нощі́ заря́ явля́єм, пре́лести тьму сія́нієм слове́с твої́х, благоче́стно взива́я отгна́л єси́: превозноси́мий отце́в і нас Бо́же, благослове́н єси́.","Богородичен: Імі́я житіє́, сло́вом, Богови́дче, му́дрости просвіще́но, Луко́, Ді́ви Рождество́ я́вственно ісписа́л єси́, і іко́нами любе́зно вообрази́л єси́: Є́йже покланя́ємся ві́рно, Христа́ сла́в'яще."]},{"h":"Пісня 8","ps":["Ірмос: На горі́ святі́й просла́вльшася, і в купині́ огне́м Присноді́ви Моїсе́йові та́йну я́вльшаго, Го́спода по́йте, і превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Росода́тельною му́дростію слове́с твої́х, і ту́чами благода́ті Боже́ственния, пре́лести пещ погаси́л єси́, ві́стник Госпо́день, і священнопропові́дник, Богому́дре, бив.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Я́ко кра́сния но́ги твоя́, всеблаже́нне, мир благовіству́ющаго, всяк ум преізві́стно прейму́щ: Єго́же превозно́сим і славосло́вим во ві́ки вся.","Світ ми́ра, просвіща́ти во тьмі сідя́щия, яви́ тя Христо́с, О́тча Существа́ Сія́ніє, Госпо́дь Сла́ви, Єго́же превозно́сим во ві́ки.","Богородичен: Во утро́бі всели́вшагося Ді́ви, і от Нея́ стра́шно і па́че сло́ва, дре́вняго Ада́ма обнови́вшаго Го́спода, поє́м і славосло́вим во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Тя Неіскусобра́чную Ма́тер Бо́га Ви́шняго, Тя па́че ума́ ро́ждшую Сло́вом воі́стину Бо́га, ви́шшую пречи́стих сил, немо́лчними славословле́нії велича́єм.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Пропові́дник бил єси́ всеми́рнаго спасе́нія, Єва́нгельським пропові́данієм: свяще́нная же і благознамени́тая труба́, вдохнове́нієм ди́шущи Ду́ха показа́лся єси́, священноглаго́льниче всече́стне.","Приспів: Святи́й апо́столе і євангели́сте Луко́, моли́ Бо́га о нас.","Дія́нії украша́єм Спа́сових апо́столов, сія́ от Бо́га подви́жим ві́рним написа́л єси́, я́коже о́браз одушевле́нний при́сно пребива́ющ об'яви́в, священнопропові́дниче всесла́вне.","Стал єси́ у́бо Луко́, я́коже пости́г Богонача́льниче жела́ній кра́йнійшеє: Христу́ бо предста́л єси́, подає́маго от Него́ насища́яся Богови́дінія. Ті́мже тя всі ублажа́єм.","Богородичен: Тя Непристу́пнаго Бо́га носи́вшую на об'я́тіїх, на Небесі́х поє́маго от вся́кия си́ли, і Тобо́ю нам да́рующа всегда́ спасе́ніє, Богома́ти, велича́єм."]},{"h":"Світилен","ps":["Луко́ Христо́в апо́столе, таї́нниче неізрече́нних, і язи́ков учи́телю, с Па́влом Боже́ственним, і пречи́стою Богоро́дицею, Єя́же Боже́ственную іко́ну от любве́ ізобрази́л єси́: моли́ Богови́дче, о нас блажа́щих тя, і соверша́ющих свяще́нноє твоє́ успе́ніє, всему́дре тайноглаго́льниче.","Я́ко ученика́ благода́ті, і спослі́дователя Па́влова, і словопи́сця ізя́щнійша Боже́ственнаго Єва́нгелія, похва́лим: Сло́ва бо воплоще́ніє і вочелові́ченіє, і Стра́сті, блаже́нне, пропові́дал єси́. Тім соше́дшеся ві́рно, Луко́, досто́йно тя почита́єм.","Богородичен: Неізрече́нно бисть рожде́ніє Пренепоро́чния Неві́сти, я́ко би́вши чисті́йший храм, Богоро́дице, Сові́том бо Преві́чним в Тя все́льшася, родила́ єси́ Бо́га Сло́ва. Тім пою́ще Рождество́ Твоє́, велича́єм досто́йно, Всенепоро́чная."]}],"notes":[]},{"u":"Канон великомучениці Параскеві, нареченій П’ятниці","e":"Canon to the Great Martyr Paraskevi, called Friday","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́ і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Сві́том Боже́ственним освіти́вшися сви́ше, мрак отжени́ неразу́мія моєго́ і пода́ждь мі моли́твами твої́ми, Параске́во, благода́ть, воспіва́ти твої́х, му́ченице, чуде́с мно́жества.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Со́лнця світлі́йши, я́ко і́стинно возсія́ла єси́ у́тро, утвержде́ніє Це́ркве би́вши Христо́ви, озари́ла єси́ луча́ми по́двигов, му́ченице Параске́во, твої́ми чудеси́ ми́ра конці́.","Жениха́, безсме́ртнаго Христа́, возлюби́вши, я́ко ві́рою Того́ стра́сті о́бщниця показа́лася єси́ і восприя́ла єси́ ві́чноє Ца́рство і віне́ць нетлі́нний, му́ченице Параске́во сла́вная.","Богородичен: Ді́во Всенепоро́чная, Христа́ роди́вшая, і Сего́ в ложесна́х понесла́ єси́, істинноімени́тая, разріши́ мрак душі́ моєя́ і просвіти́ м'я, да пою́ Тя."]},{"h":"Пісня 3","ps":["Ірмос: Лук си́льних ізнемо́же, і немощству́ющії препоя́сашася си́лою, сего́ ра́ди утверди́ся в Го́споді се́рдце моє́.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Па́лицями неми́лостивно біє́ма, ра́довашеся, ли́стом сокруша́ємим і косте́м вку́пі, приснопа́м'ятная му́чениця Параске́ва, вопію́щи: нічто́же м'я разлучи́ть от любве́ Твоєя́, Христе́.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Уста́ нечести́вих, глаго́лющая беззако́ніє на пра́веднаго, і язи́к велері́чив загради́шася, му́чениця Параске́ва вопія́ше, Спа́са пропові́дающи.","Крове́й твої́х кропле́нії безбо́жия огнь погаси́ла єси́, многострада́льная му́ченице Параске́во, і ві́рних ра́зуми просвіти́ла єси́.","Богородичен: Глаго́ли благочести́вно ісполня́ються Іса́їїни: Ді́ва бо родила́ єсть во пло́ті Жизнода́вця Христа́, Спа́са душ на́ших."]},{"h":"Сідален, глас 4","ps":["Посто́м украси́вши чистоту́ душе́вную, луча́ми страда́нія просвіща́єши ві́рния, му́ченице многострада́льная Параске́во. Тім твой святи́й і світоно́сний день ві́рою соверша́юще, благоче́стно вопіє́м: я́ко імі́я дерзнове́ніє ко Го́споду, моли́ спасти́ся нам.","Слава, і нині: Обнови́ла єси́, Чи́стая, Боже́ственним Рождество́м Твої́м істлі́вшеє во страстеіх земноро́дних ме́ртвенноє существо́, і воздви́гла єси́ вся от сме́рти к жи́зні нетлі́нія. Ті́мже Тя по до́лгу блажи́м всі, Ді́во Препросла́вленная, я́коже прорекла́ єси́."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́, во о́блаці ле́гці при́йде Ісу́с Пребоже́ственний нетлі́нною дла́нію і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Уязви́вшися любо́вію Христо́вою, ополче́нія мучи́тельськая крі́постію твоє́ю умертви́ла єси́, благода́ть істоча́єши присноживо́тную, ю́же, страсте́й ра́ди, мздовоздая́ніє восприя́ла єси́, Параске́во, му́чениць Христо́вих добро́та.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Превозше́дши вся любо́вію Христа́, Жениха́ твоєго́, плотську́ю же любо́во возненави́дівши, крі́пко болі́зненная страда́нія претерпі́ла єси́, му́ченице Параске́во, вопію́щи: не разлучи́ мене́, Христе́, от жела́нія Твоєго́, муче́нія по́двиг соверши́ти.","Отве́ргши ми́ра суєту́ всю, Бо́гу Єди́ному приліпи́лася єси́, Параске́во му́ченице, і болі́зні страда́нія претерпі́ла єси́, неві́сто Бо́жия, мужеу́мная.","Богородичен: Сни́де, я́ко дождь на руно́, во утро́бу Твою́ Госпо́дь, я́коже рече́ дре́вле проро́к, Всенепоро́чная, Єго́же во двух существа́х родила́ єси́, Єму́же взива́єм: сла́ва си́лі Твоє́й, Го́споди."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой Світ, в мир прише́л єси́, Світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Світ незаходи́мий всели́ся в душі́ твоє́й, да доброді́телію сія́єши, озаря́я тебі́ непреста́нно сла́в'ящия.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Струю́, му́ченице Параске́во, нечести́ваго безбо́жия ізсуши́ла єси́, і тече́нії кро́вними, непра́ведно пролива́ємими, огнь пре́лести погаси́ла єси́.","Ум іму́щи прозра́чен, проро́чеськаго да́ра сподо́билася єси́, і хотя́щая би́ти всім я́ві предглаго́лала єси́, Параске́во многострада́льная.","Богородичен: Ма́ти Бо́жия, душ на́ших я́зви ісціли́ла єси́, роди́вши Бо́га Сло́ва неізрече́нно. Сего́ ра́ди всі ро́ди блажа́ть Тя."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею кро́вію.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Возсія́вши із Ри́ма, я́ко со́лнце сві́тлоє, свята́я му́ченице, мрак де́монський от челові́к отгна́ла єси́ мольба́ми твої́ми, Параске́во многострада́льная.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Ісціле́нія приє́млють приходя́щії прикоснове́нієм к ра́ці моще́й твої́х: кровоточи́вії і прокаже́ннії очища́ються, і отбіга́ють де́монськия полки́, призива́нієм свята́го твоєго́ і́мені.","У́треневала єси́ ко Христу́, невече́рнему Со́лнцю, і Того́ світлостьми́ ду́шу, богому́драя, і се́рдце озари́ла єси́, Параске́во честна́я, і к Сві́ту Тро́їчеському, ра́дуяся, прешла́ єси́.","Богородичен: Ісціли́ душі́ моєя́ стра́сті, Всенепоро́чная, безстра́стія ро́ждшая Істо́чник, і отжени́ томи́тельство, непреста́нно стужа́ющеє се́рдцю моєму́."]},{"h":"Кондак, глас 3","ps":["Всесвято́є і непоро́чноє муче́ніє прине́сши, я́ко ві́но пречестно́є, безсме́ртному Жениху́ Христу́, а́нгельськоє ликостоя́ніє возвесели́ла єси́ і побіди́ла єси́ де́монськия ко́зні. Сего́ ра́ди тя че́стно ві́рою чтим, му́ченице Параске́во многострада́льная."]},{"h":"Ікос","ps":["Кто ізглаго́леть си́ли Госпо́дня? Іли́ кто пові́сть страда́нія твоя́ і доброді́телі, му́ченице? Іли́ кий язи́к воспі́ти возмо́жеть по досто́їнству? Но аз, недосто́йний, воспі́ти покуша́юся, хвали́ти же і сла́вити Влади́ку Жизнода́вця, да́вшаго тебі́ на три́знищі крі́пость мучи́телей не убоя́тися, іспові́дающей І́стиннаго Бо́га. Сего́ ра́ди тя чтим ві́рою і любо́вію, му́ченице Параске́во многострада́льная."]},{"h":"Пісня 7","ps":["Ірмос: Спаси́й во огні́ авраа́мськия Твоя́ о́троки і халде́ї уби́в, я́же Пра́вда пра́ведно уловля́ше, препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Голуби́це, кри́ла іму́щи злата́я і ору́жієм храни́ма кре́стним, ага́ряни, в нощі́ гра́ду твоєму́ прибли́жившіяся, отгна́ла єси́, спа́сши ві́рния от уби́йства, му́ченице Параске́во, пою́щия: препі́тий оте́ць на́ших Бо́же, благослове́н єси́.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Многообра́зния болі́зні претерпі́вши Христа́ ра́ди, му́ченице Параске́во, неболі́зненний у Него́ обріла́ єси́ поко́й, і ра́дующися, взива́єши: препі́тий оте́ць на́ших Бо́же, благослове́н єси́.","Коль непобіди́мь твой ра́зум, Параске́во честна́я! Я́ко от нача́льников ли́ка мучи́телей мук не убоя́лася єси́. С ни́миже бра́вшися, сконча́лася єси́, я́ко служи́тельниця та́йни Боже́ственния сла́ви, пою́щи: препі́тий оте́ць на́ших Бо́же, благослове́н єси́.","Богородичен: Благослове́н Плод благослове́ннаго Твоєго́ чре́ва, Єго́же благослов'я́ть небе́сния си́ли і челові́честії собо́ри восхваля́ють, нас ізба́вльшаго кля́тви дре́внія, Благослове́нная, пою́щих: препі́тий оте́ць на́ших Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Боже́ственними світлостьми́ Со́лнця ми́сленнаго просвіти́вшися, му́ченице всехва́льная Параске́во, нощ претекла́ єси́ безбо́жия, пою́щи єдиноми́слієм душі́: Го́спода воспіва́йте діла́ і превозносі́те Єго́ во ві́ки.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Я́ко а́гниця, я́ко нескве́рная ю́ниця, я́ко боже́ственная голуби́ця, я́ко самово́льноє заколе́ніє, привела́ся єси́, му́ченице Параске́во, Зижди́телю твоєму́, і я́ко же́ртва непоро́чна, принесла́ся єси́, согла́сно пою́щи: Го́спода по́йте діла́ і превозносі́те Єго́ во ві́ки.","Сві́тлу себе́ от крове́й ри́зу муче́нієм обложи́ла єси́, Параске́во, до́бляя му́ченице, совле́кшися і́стинно тлі́ннаго со гріхи́ челові́ка, ра́достно воспіва́ющи: Го́спода по́йте діла́ і превозносі́те Єго́ во ві́ки.","Богородичен: Во слід Тебе́ теко́ша жени́, ми́ра сладково́ннаго ві́дуще, Всечи́стая Богоневі́сто, єди́на Неіскусобра́чная, із утро́би Твоєя́ возсія́вшаго Єдиноро́днаго Си́на, Христа́ Бо́га, і с Тобо́ю ца́рствують і́стинно, пісносло́в'яще Єго́ во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","В небе́сний черто́г все́льшися, ді́во Параске́во всечестна́я, і неви́димих добро́т разу́мно наслади́вшися, восприї́мши неізрече́нную сві́тлость, просвіти́ пою́щия і велича́ющия тя.","Приспів: Свята́я великому́ченице Параске́во, моли́ Бо́га о нас.","Віне́ць восприя́ла єси́ на главі́ твоє́й, Параске́во доблеу́мная, я́ко сконча́вши тече́ніє і сохрани́вши ві́ру непоколеби́му, і пра́ведних чи́ни ра́достно тя прия́ша. Тім ни́ні ублажа́єм тя.","Подає́ши ісціле́ній ка́плі тре́бующим, я́ко от істо́чника, всебога́тая му́ченице Параске́во, уставля́ющи то́ки неду́гов і страсте́й отгоня́щи зной, і сердця́ благочести́вих напая́ющи ко благопло́дію Боже́ственних дія́ній.","Богородичен: Му́дрости Вмісти́лище, па́че ума́ лу́чшаго, яви́лася єси́, Отрокови́це Всенепоро́чная, одушевле́н же престо́л і двер. Тім я́ко Цари́цю Тя возлю́бльше ді́ви, во слід Тебе́ приведо́шася, Богоотрокови́це."]},{"h":"Світилен","ps":["Я́ко ши́пок красні́йшій от терно́внаго прозябла́ єси́ ко́рене, ді́во Параске́во, оброше́нієм, му́ченице, свяще́ннаго страда́нія обагри́вшися кро́вію. І ни́ні боже́ственную твою́ па́м'ять творя́щия любо́вію спаса́й ни от бід.","Слава, і нині: Стоя́ще о́крест Тебі́ ді́ви богому́дрия, Богороди́тельнице Марі́є, я́ко Цари́це ро́дом, Твоєму́ Си́ну приведо́шася невістолі́пно, Пречи́стая, я́ко Царю́ вся́чеських, Єго́же, Ма́ти Ді́во Отрокови́це, о нас моли́."]}],"notes":[]},{"u":"Канон святителю Іоні Новгородському","e":"Canon to St Jonah of Novgorod","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Тріста́ти крі́пкия, Рожде́йся от Ді́ви, безстра́стія во глубині́, душі́ трича́стноє потопи́, молю́ся, да Тебі́, я́ко в тимпа́ні, во умерщвле́нії тілесе́ побі́дноє воспою́ пі́ніє.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Ізбра́ тя благода́ть, о́тче, от утро́би ма́тере твоєя́ поста́вити тя проро́ка лю́дем свої́м, хода́тайствовати ко Го́споду о спасе́нії ми́ра і оставле́нії неві́ждеств їх, блаже́нне.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Руко́ю вели́каго архієре́я Іо́ни со і́же о нем собо́ра свяще́нних муже́й судо́м приє́млеши пома́заніє архієре́йства, Ду́хом воздвиза́єм, Іо́но, і па́стир вели́кому гра́ду, свяще́нне, полага́єм.","Блаже́ннаго Михаї́ла сби́стся на тебі́ прорече́ніє, не вні́шнюю бо на тебі́ нищету́ зря́ще, но вну́треннєє преспі́яніє душі́ твоєя́ духо́вними очеси́ смотря́я, а́ще і єще́ о́трочищу ті су́щу, блаже́нне.","Богородичен: Пресві́тлая свіще́ Со́лнця сла́ви, душі́ моєя́ огнь, угаше́нний при́сно уни́нієм, возжзи́, боже́ственних діл єле́єм, Пречи́стая, напая́ющи, да ві́рою і любо́вію при́сно Тя сла́влю, Богороди́тельнице."]},{"h":"Пісня 3","ps":["Ірмос: С висоти́ снизше́л єси́ во́лею на зе́млю, преви́шше вся́каго нача́ла, і смире́нноє возне́сл єси́ із а́да преіспо́дняго єстество́ челові́чеськоє: ність бо свят па́че Тебе́, Человіколю́бче.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","От ю́ности твоєя́ боже́ственноє просвіще́ніє, Іо́но, на тебі́ сія́ше, я́коже преподо́бний прови́ді, і́же ми́ру юро́д, Бо́гу же прему́др: я́ко Бо́гу ізбра́н єси́ із чре́ва ма́тере твоєя́, свяще́нне.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Мир усмири́ся моли́твами твої́ми, ієра́рше, во твоє́м єпи́скопстві, но, я́ко тогда́, і ни́ні Бо́жиє человіколю́біє умоли́ прилі́жно в ми́рі утверди́тися ми́ру, Іо́но.","Плоди́ Го́споду нача́ток діл твої́х прине́сл єси́, плоди́ же землі́ моли́твами твої́ми умно́жил єси́. І ни́ні моли́, блаже́нне, землі́ на́шей плодоно́сіє при́сно подава́ти, я́ко благопослу́шна тя імі́єм.","Богородичен: Є́вину дре́внюю кля́тву, Христа́ ро́ждши, Ма́ти Чи́стая, пресві́тло разріши́ла єси́, і́же всіх вінчава́ющаго благослове́ньми: ність бо, Пречи́стая, па́че Тебе́, іни́я Помо́щници."]},{"h":"Сідален, глас 4","ps":["Доброді́тельми світя́ся, о́тче, па́ствити Христо́ви о́вці поставля́єм, і преподо́бнаго Се́ргия красе́н храм внутр єпи́скопії воздви́гл єси́. Я́ко душе́ю люб'я́ того́, по́двиги єго́ почита́я і смоли́твенника себі́ о ста́ді твоє́м ко Го́споду полага́я, ни́ні сра́дуєшися єму́, о́тче свяще́нне, моли́ спасти́ся душа́м на́шим.","Богородичен: Обнови́ла єси́, Чи́стая, боже́ственним Рождество́м Твої́м істлі́вшеє во страстеіх земноро́дних ме́ртвенноє существо́ і воздви́гла єси́ вся от сме́рти к жи́зні нетлі́нія. Ті́мже Тя по до́лгу блажи́м всі, Ді́во Препросла́вленная, я́коже прорекла́ єси́."]},{"h":"Пісня 4","ps":["Ірмос: Любве́ ра́ди, Ще́дре, Твоєго́ о́браза, на Кресті́ Твоє́м стал єси́, і раста́яшася язи́ци: Ти бо єси́, Человіколю́бче, крі́пость моя́ і хвале́ніє.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Боже́ственнаго Предте́чі, вели́каго Іоа́нна, храм свяще́нний воздви́гл єси́, я́ко ві́рен, ду́шу тому́ і ті́ло в снабді́ніє возлага́я, о́тче свяще́нне.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Я́ко рачи́тель і подража́тель тепл Крести́телю Госпо́дню показа́лся єси́, ті́мже в хра́мі єго́, єго́же тому́ созда́л єси́, ті́ло твоє́ полага́єши, і во двори́ єго́ прия́тися жела́я.","Возлюби́л єси́, архієре́ю, свяще́нних муже́й пі́сньми восхваля́ти свяще́нния їх па́м'яті, я́ко рачи́тель добро́ти їх і подража́тель дія́ній боголюбе́зних.","Богородичен: Імі́я Тя Помо́щницю, кого́ убою́ся когда́ іли́ устрашу́ся? Кто же, хотя́ ско́рбная навести́ рабу́ Твоєму́, і не устраши́ться Тебі́, Пречи́стая, і не паде́ть под но́зі?"]},{"h":"Пісня 5","ps":["Ірмос: Нечести́вії не у́зрять сла́ви Твоєя́, Христе́, но ми Тя, Єдиноро́дне, Оте́чеськия сла́ви Сія́ніє Божества́, от но́щі у́тренююще, воспіва́єм Тя, Человіколю́бче.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Приноси́моє я́ко че́стно возложе́ніє Бо́гу і освяще́нно первопресто́льником Українським, Іо́ною, твоє́ свяще́нноє па́стирства возведе́ніє, я́ко пасу́щу ті Госпо́дні лю́ди, Іо́но святи́телю, преподо́бієм і кро́тостію.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","А́ще і на преставле́ніє митрополи́том Іо́ною зово́м самі́м погребсти́ єго́, отре́клся єси́ ста́рости ра́ди прийти́, Іо́но свяще́нне, оба́че обіща́лся єси́ єму́ ви́діти того́ по своє́м преставле́нії во сві́ті Христо́ві.","Пі́сньми поче́л єси́ па́м'ять ієра́рха, Іо́ни митрополи́та, і хвала́ми, я́ко досто́йно, ублажи́л єси́ того́: сам ни́ні, ієра́рше Іо́но, прича́ствуєши похвала́м єго́ і по сотворе́нію твоєму́ к бли́жнему восприє́млеши.","Богородичен: Низложи́, Влади́чице, враго́в мої́х шата́ніє, Пренепоро́чная, Тя бо і́мам і предста́тельницю, і наде́жду, і по́мощ крі́пкую. Ти м'я соблюди́, Чи́стая, наві́та вра́жия, ізбавля́ющи ла́янія тіх."]},{"h":"Пісня 6","ps":["Ірмос: Пучи́ною жите́йською дія́ньми мої́ми снидо́х во ад, но, я́ко от ки́та Іо́на, та́ко вопію́: із глубини́ зол возведи́, молю́ся, Си́не Бо́жий і Сло́ве.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Прильпе́ любо́вію душа́ твоя́ ко Госпо́дню Крести́телю, святи́телю богоблаже́нне, ті́мже ті́ло твоє́ честно́є в честні́м хра́мі єго́ нетлі́нно во мно́га лі́та соблюде́но яви́ся.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Красота́ гові́нія твоєго́ є́же ко Го́споду привлече́ благода́ть благолі́пію душі́ твоєя́, свяще́нне, і возведе́ тя Вели́кому Нову́граду отця́ і первопресто́льника, Госпо́дня свяще́нства преподо́бна показа́.","Просла́ви тя Госпо́дь, Іо́но, ті́ло твоє́ соблюде́ во мно́га лі́та нетлі́нно, явля́я тя о́бщника раб Свої́х, ї́хже подража́тель в житії́ бил єси́, сим і по сме́рті досто́йно соублажа́єшися, блаже́нне.","Богородичен: Всесвята́я Ді́во, Предста́тельнице і покро́ве всіх ві́рних, предста́ни і ізба́ви ни враг на́ших нападе́нія, і от вся́кия ско́рби, і стра́шнаго Суда́ іспита́нія, да ві́рою при́сно пою́ Тя."]},{"h":"Кондак, глас 4","ps":["Сви́ше прия́л єси́ Боже́ственную благода́ть хода́тайствовати Бо́гу і челові́ком, я́ко архієре́й возноше́ніє вознося́, і мир лю́дем твої́м снося́, і оби́ліє плодо́в, Іо́но блаже́нне; ти бо єси́ Вели́каго Нова́града похвала́ і су́щих о нем ра́дость."]},{"h":"Ікос","ps":["Похва́лим досто́йно ни́ні ієра́рха, я́ко от чре́ва ма́тере своєя́ ізбра́н Бо́гу во освяще́ніє, і, о́трочищ єще́ сий, пронарече́н во архієре́йство гра́ду своєму́ от Бо́га. Ті́мже не от челові́к проізведе́н архієре́й, но сви́ше пронарече́н і Ду́хом пома́зан, священноді́йствуя богоприя́тно, і умире́ніє, і тишину́ моли́твами свої́ми да́руєть, і оби́ліє плодо́в. Той бо Вели́каго Нова́града сла́ва і всіх, і́же о нем, ра́дость."]},{"h":"Пісня 7","ps":["Ірмос: Авраа́мстії іногда́ во Вавило́ні о́троци пе́щний пла́мень попра́ша, пі́сньми взива́юще: оте́ць на́ших Бо́же, благослове́н єси́.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Зи́ждеши Боже́ственному і́мені бога́тною руко́ю в пусти́нях уда́лено, Іо́но, свяще́нния хра́ми вели́ких богоуго́дник, боже́ственних архієре́й с преподо́бними.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Но́ву оби́тель составля́єши вели́ких тріє́х ієра́рх і мона́шестій черті́ благоути́шно приста́нище, о́тче, мі́стним же удале́нієм обруча́я їм безмо́лвіє.","Виногра́д насажда́я Бо́гу, огра́ду свяще́нную, вино́ ізнося́щую веселя́щеє, в свяще́нних хра́міх боже́ственноє пі́ніє, І́же в Тро́йці Єди́ному, хвали́му і благослови́му Бо́гу оте́ць на́ших.","Богородичен: Єди́ну Всесвяту́ю, Єди́ному Бо́гу вселе́ніє єди́но пречи́сто, от Іоаки́ма і А́нни ражда́єму, свяще́нним хра́мом почита́я, я́ко в нем воспіва́ти всепі́тоє Ді́ви Рождество́."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Кро́ткоє і молчали́воє нра́ва твоєго́ восприє́м, Госпо́дь, блаже́нне, поста́ви тя па́стиря лю́дем Свої́м, на кого́ бо при́зрить? Но на кро́ткаго і молча́щаго, трепе́щущаго слове́с Єго́.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Уста́ вдов благослови́ша тя, заступле́нія от тебе́ сподо́бльшеся, ієра́рше блаже́нне, благоугожда́ющаго Бо́гу, по непоро́чному І́ову, і оби́димия от наси́лія ізима́ющаго.","Лю́діє твої́, священнонача́льниче преподо́бне, сі́товаху сиротства́ своєго́ в твоє́м к Бо́гу отше́ствії, до́браго па́стиря своєго́, ни́ні же свяще́нною па́м'ятію твоє́ю возра́довашася вся́чеськая.","Богородичен: На Тя всю наде́жду спасе́нія моєго́ возложи́х, Богома́ти Неіскусобра́чная, і Тя призива́ю при́сно на по́мощ: спаси́ м'я от напа́стей і печа́лі врага́, разріши́ плени́цю зол мої́х і Суда́ м'я ісхити́."]},{"h":"Пісня 9","ps":["Ірмос: Сотвори́ держа́ву ми́шцею Своє́ю, низложи́ бо си́льния со престо́л і вознесе́ смире́нния Бог Ізра́їлев, в ни́хже посіти́ нас Восто́к с висоти́ і напра́вил ни єсть на путь ми́ра.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","Блаже́ннаго Євфи́мія престо́л наслі́довал єси́, свяще́нне Іо́но, я́ко подража́тель доброді́телей єго́ бил єси́ і, пі́сньми сего́ ублажи́в па́м'ять ізря́дно, сам ни́ні обществу́єшися хвала́м єго́, я́ко соводворя́єшися єму́ во Сві́ті незаходи́мім.","Приспів: Святи́телю, о́тче Іо́но, моли́ Бо́га о нас.","В зе́млю кро́тких со архієре́ї досто́йно всели́лся єси́, ієра́рше Іо́но, кро́ткаго Учи́теля учениче́. Тому́ предста́ни о нас, пою́щих па́м'ять твою́, і іспроси́ нам собла́знов оставле́ніє, і шу́їя ча́сти в день Суда́ ізбавле́ніє, і лю́тия геє́нни, блаже́нне.","Не ізнемо́жеть всяк глаго́л, і́же от Бо́га, убо́га тя і сироту́ Оте́ць сиро́т приє́млеть, Бог, І́же на престо́лі со кня́зі посади́ тя, лю́дем Свої́м я́ко досто́йна па́стиря проізводя́, отця́ сирота́м і засту́пника вдова́м те́пла положи́ тя, Іо́но блаже́нне.","Богородичен: Просвіти́, Чи́стая, любо́вію чту́щих Тя і велича́ющих, разріши́ стра́сті на́ша. Тім, Ді́во, уста́ви бу́рю, лука́ваго собла́зни от среди́ отжени́, ва́рвари покори́ правосла́вним лю́дем моли́твами Твої́ми."]},{"h":"Світилен","ps":["Трисо́лнечнаго Сві́та, сла́ви сія́нієм, тріє́х учи́телей сві́том озари́вся, вся просвіща́єши, просія́в ді́тельми і благода́тію, преподо́бне священнонача́льниче.","Богородичен: Сла́дость а́нгелов, скорб'я́щих ра́досте, христия́н предста́тельнице, Ді́во, Ма́ти Госпо́дня, заступи́вши ни, спаси́ от ві́чнаго муче́нія."]}],"notes":[]},{"u":"Канон апостолу Филипу","e":"Canon to the Apostle Philip","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Пресві́тлими луча́ми Христо́ви Боже́ственния сві́тлости наслажда́яся я́сно, богопропові́дниче Фили́ппе, твої́ми по прича́стію заря́ми нас просвіти́.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","О́тчую тебі́ сла́ву Собо́ю показа́вий, Фили́ппе, ли́ку ученико́в тя Христо́с вчини́, твою́ прові́дий доброді́тель, богоблаже́нне.","Ни́ні не в гада́ніїх зри́ши, ніже́ сі́ніх, ніже́ зерца́ліх, всему́дре, Істо́чника благи́х, жела́ній коне́чноє, Христа́, но лице́м зри́ши я́вственно к Лицю́.","Богородичен: Оскуде́вшим нача́льником от колі́на Іу́дова, Пречи́стая, Син Твой і Бог прише́д, вождь землі́ конце́м і́стинно ни́ні воцари́ся."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Ти, іспо́лнен сві́та ді́ятельнаго виді́нія, Сві́ту вели́кому, би́вшу с на́ми, сподо́бился єси́ Христу́ служи́ти, Фили́ппе богоглаго́ливе.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Степе́нь догма́тов благочести́вих твоє́ тайново́дствіє благочести́во яви́ся, тім бо Си́на позна́хом соєсте́ственна і соєдине́нна су́ща Роди́телю.","Сві́щник бил єси́ злат, сія́я челові́ком присносу́щний світ і просвіща́ющ їм вселе́нную я́ві позна́нієм, Фили́ппе всеїзя́щнійше.","Богородичен: На Тя, Пресвята́я Чи́стая, наді́явся, да не отпаду́ Твоєго́ ча́янія, но, я́ко Ма́ти ми́лостивная человіколюби́ваго Бо́га, сіте́й м'я врага́ ізба́ви."]},{"h":"Сідален, глас 8","ps":["Тучено́сен о́блак духо́вний і́стинно показа́лся єси́ су́щим на землі́, напая́я, я́ко ни́ву, та́їнственно сердця́ на́ша; проте́к сло́вом, напая́єши конці́ і дождь пролива́єши ми́ра от ра́ки. Тім, дохну́в неві́рним сердця́м воню́ Ду́ха, в ни́хже сокро́вищствовал єси́, апо́столе Фили́ппе, моли́ся Христу́ Бо́гу гріхо́в оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять твою́.","Слава: І́дольськую лесть низложи́л єси́, Спа́сови стра́сті возжелі́в, Фили́ппе, сла́вне, яви́лся єси́ ми́ру, небе́сная всім істоча́я чудеса́ і язи́ков бив, всеблаже́нне, апо́стол. Тім твою́ па́м'ять досто́йно чтим, пісносло́в'яще: Госпо́день апо́столе, моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять твою́.","І нині: В напа́сти многоплете́нния впад от враг ви́димих і неви́димих, бу́рею одержи́м безчи́сленних согріше́ній мої́х, і, я́ко к те́плому заступле́нію і покро́ву моєму́, Чи́стая, ко приста́нищу притека́ю Твоєя́ бла́гости. Ті́мже, Пречи́стая, із Тебе́ Воплоще́нному безсі́менно моли́ся прилі́жно о всіх рабі́х Твої́х, непреста́нно моля́щихтися, Богоро́дице Пречи́стая, моля́щи Єго́ при́сно согріше́ній оставле́ніє дарова́ти воспіва́ющим досто́йно сла́ву Твою́."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, честна́я Це́рков боголі́пно поє́ть, взива́ющи, от сми́сла чи́ста, о Го́споді пра́зднующи.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Со́лнця селе́ніє, Христа́, су́щаго Сві́та, і храм показа́лся єси́ вмісти́телен Того́ сві́тлости, і не́бо, сла́ву Бо́жию челові́ком пові́дая.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Во істлі́вшеє страстьми́ челові́чество ти вложе́н, Бо́жия соль, от Христа́, того́ ізсуши́ гни́лость лю́тую, Боговіща́телю достосла́вне.","Си́лою, Фили́ппе, Христо́вою укріпля́єм, де́монськаго полка́ і злові́рних яви́лся єси́ си́льншій, су́щим на землі́ вопія́ жи́зні боже́ственния благові́стіє.","Богородичен: Приста́нище благоти́хоє Христо́с яви́ ві́рою і любо́вію Тя, і́стинную Влади́чицю Всенепоро́чную, от со́вісти чи́стия Богоро́дицю пропове́дающим."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті ду́ші любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, і́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Я́да душегуби́тельнаго вра́жия враче́бними твої́ми дла́ньми, богоглаго́ливе, ізсуши́в, смертоно́сною глубино́ю держи́мия, лю́тия болі́зні избавля́я.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Огнедохнове́нен весь яви́лся єси́ Паракли́товим наше́ствієм і благода́тію, Фили́ппе, іззя́бшия безбо́жия зимо́ю, теплото́ю ві́ри оживотвори́л єси́.","Близ бил єси́ Христа́, дає́мия ті зари́ несре́дственно приє́мля, просвіща́я к тебі́ притека́ющия і приводя́ ти́я Соді́телю Твоєму́.","Богородичен: Сло́вом вся соді́тельствуя і му́дрим про́мислом окормля́я єди́н, я́ко хо́щеть Госпо́дь, за благоутро́біє зи́ждеться із Тебе́ і плоть несказа́нно, Пречи́стая, бива́єть."]},{"h":"Пісня 6","ps":["Ірмос: Ять бисть, но не удержа́н в пе́рсіх ки́тових Іо́на: Твой бо о́браз нося́, Страда́вшаго, і погребе́нію да́вшагося, я́ко от черто́га от зві́ря ізи́де. Приглаша́ше же кустоді́ї: храня́щії су́єтная і ло́жная, ми́лость сію́ оста́вили єсте́.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Одержа́щу і губ'я́щую зря пре́лесть вра́жию челові́чеський род, Твоя́ стрі́ли, ізощре́нния апо́столи, напря́г, іспусти́л єси́ і разве́рзл єси́ бре́нная уста́ змі́єва, всіх от того́ вре́да і тлі, Спа́се, ісціля́я.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Ви́шнім сія́нієм блиста́я, яви́лся єси́, я́коже мо́лнія, вселе́нній світя́, і я́ко гора́, сла́дость іска́пающая, я́ко роса́ боже́ственная, с небесе́ па́дающая, я́ко апо́стол ізбра́н, дванадесяточи́сленний полк ісполня́я ученико́в Христо́вих, всеблаже́нне.","Научи́вся Твоєя́ та́йни глубині́, Боже́ственний учени́к, я́ко реку́ ми́ра, наводня́ющу сла́дости пото́к, я́ко потопля́ющую волну́, сла́ву язи́ков, Тя пропові́да велегла́сно і Твоє́ сла́вноє істоща́ніє, Бла́же, є́же о нас благовісти́.","Богородичен: Умерщвля́ємия і ги́бнущия вся сме́ртію челові́ки Ти, Христа́ ро́ждши — Нетлі́нноє безсме́ртіє, призвала́ єси́ к жи́зні ві́чній, і просвіти́ла єси́ омраче́нния, і свободи́ла єси́, разріши́вши у́зи отведе́нія на́шего, Всепі́тая."]},{"h":"Кондак, глас 8","ps":["Учени́к, і друг Твой, і подража́тель стра́сті Твоєя́ вселе́нній Бо́га Тя пропові́да богоглаго́ливий Фили́пп; того́ моли́твами от враго́в пребеззако́нних Це́рков Твою́ і всяк град Твой Богоро́дицею соблюди́, Многоми́лостиве."]},{"h":"Ікос","ps":["Струю́ сло́ва пода́ждь мі, Го́споди, водно́є єстество́ соді́явий, се́рдце моє́ укріпи́, Благоутро́бне, І́же зе́млю утверди́вий сло́вом Твої́м, і просвіти́ моє́ помишле́ніє, сві́том, я́ко ри́зою, одіва́яйся, да глаго́лю і пою́ подоба́ющая і досто́йно восхвалю́ Твоєго́ уго́дника, Многоми́лостиве."]},{"h":"Пісня 7","ps":["Ірмос: О́троци во Вавило́ні пе́щнаго пла́мене не убоя́шася, но, посреді́ пла́мене вве́ржені, ороша́ємі, поя́ху: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Я́ко світ, посла́лся єси́ стріли́ подо́бієм, апо́столе, світоза́рними блиста́нії просвіща́я ві́рою зову́щия: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Бога́тими світоли́тії Боже́ственнаго, блаже́нне, пропові́данія сія́я сві́тло, во тьмі су́щия піснопі́ти просвіти́л єси́: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Виті́йськая буєсло́вія і слове́сную всю лю́тость крі́пким сло́вом ві́ри побіди́в, піл єси́: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших.","Богородичен: В єстества́х пресу́щественно, Ді́во, двух родила́ єси́ соєдине́нних, Чи́стая, неслія́нно Христа́, Єму́же зове́м: благослове́н єси́, Го́споди, Бо́же оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: За зако́ни оте́чеськия блаже́ннії во Вавило́ні ю́ноши, предбі́дствующе, царю́ющаго оплева́ша повелі́ніє безу́мноє, і совоку́плени, і́мже, не свари́шася огне́м, Держа́вствующему досто́йную воспіва́ху піснь: Го́спода по́йте, діла́, і превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Сві́та тя ми́ра соверши́ Оте́чь Світ, Сло́во Іпоста́сноє, ізбра́вий апо́стола от ми́ра, треблаже́нне, і, вооружи́в Боже́ственною си́лою Своє́ю, посла́, я́ко ору́жника непобіди́ма, вопію́ща: Го́спода по́йте діла́ і превозносі́те во вся ві́ки.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Си́лою Боже́ственною укріпля́єм, апо́столе, проти́вния полки́ побіди́л єси́, свирі́поє ополче́ніє тіх разруши́в, мир бо неот'я́тний жре́бій взем, ми́рноє устроє́ніє насади́л єси́ ми́ру, — Го́спода воспіва́йте діла́, — вопія́, — і превозносі́те во вся ві́ки.","Все́ю любо́вію приліпи́лся єси́ воплоще́нному Сло́ву Бо́жию, апо́столе, учени́к Того́ бив, і Бо́жий слуга́, і тайноглаго́льник, отону́дуже от Него́ по́слан во язи́ки, пропові́дал єси́ Єго́ прише́ствіє, — Го́спода по́йте, — вопія́, — і превозносі́те во вся ві́ки.","Богородичен: Весь соєдини́ся па́че ра́зума неізмі́нно всему́ челові́честву Пребоже́ственний во утро́бі Твоє́й, Всесвята́я Ді́во. Ті́мже во дву єстеству́ зна́ється Христо́с, єди́н сий обоє́. Єму́же, пою́ще, вопіє́м: Го́спода по́йте діла́ і превозносі́те во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га челові́ком невозмо́жно ви́діти, на Него́же не смі́ють чи́ни а́нгельстії взира́ти; Тобо́ю бо, Всечи́стая, яви́ся челові́ком Сло́во воплоще́нно, Єго́же велича́юще, с небе́сними во́ї, Тя ублажа́єм.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Ни́ні неізрече́нния сла́ви і сві́та невече́рняго сподо́бився, іді́же неізглаго́ланноє єсть весе́ліє, іді́же ра́дость непреста́нная в Це́ркві перворожде́нних, іді́же пра́ведних селе́нія, за вся христия́ни моли́ся, Фили́ппе, всему́дре.","Приспів: Святи́й апо́столе Фили́ппе, моли́ Бо́га о нас.","Укра́шен добро́тою у́мнаго благолі́пія і Ца́рствія вінце́м обложе́н, богому́дре, і бога́тими світодая́нії, Фили́ппе, просвіща́єм пресу́щественнаго Сві́та сія́ньми, ра́дуяся, Влади́ки твоєго́ престо́лу, блаже́нне, предстої́ши.","Со апо́столи всі́ми честни́ми, і проро́ки, і страстоте́рпці, Фили́ппе, преподо́бними, ієра́рхи і пра́ведними, с Богоро́дицею моли́ разріше́ніє гріхо́в мно́гих і прегріше́ній да́ти очище́ніє ві́рою світоно́сную і боже́ственную па́м'ять соверша́ющим твою́.","Богородичен: Воплоще́нно Сло́во, пре́жде безпло́тно су́що, Ді́во Ма́ти, родила́ єси́. Сего́ ра́ди Тя, госпо́дственно Богоро́дицю, всі благоче́стно сла́вим, і́стиннійшеє Тебі́ нариця́ніє принося́ще, Чи́стая, Ти бо ві́рних спасе́нія ко́рень пребива́єши."]},{"h":"Світилен","ps":["Тече́ніє кра́сних твої́х ног, Фили́ппе, возврати́в, к ше́ствію небе́сному возше́л єси́, ра́дуяся, і, Тро́йце предста́в, во Отці́ ви́диши Си́на і Ду́ха Боже́ственнаго. Сего́ ра́ди ві́рою всесвяще́нную твою́ і боже́ственную пра́зднуєм па́м'ять.","Слава, і нині: Стра́шнаго іспита́нія воспомина́ю час, мно́жество бо діл мої́х ужаса́єть і устраша́єть м'я. Но уще́дри, Пречи́стая, те́плою Твоє́ю моли́твою і даждь мі спасе́ніє: єли́ко бо хо́щеши, і твори́ши, я́ко Бо́га ро́ждши, благослове́нная Марі́є."]}],"notes":[]},{"u":"Канон преподобному Никону, ігумену Радонезькому","e":"Canon to St Nikon, Abbot of Radonezh","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Прему́дростію ра́зума украша́єм, преподо́бне Ни́коне, весь Христу́ порабо́тился єси́, к Нему́ жела́ніє твоє́ імі́я, Єго́же моли́ спасти́ от бід пою́щия тя.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","О всіх Христа́ моли́, преподо́бне Ни́коне, па́м'ять твою́ любо́вію пою́щих, ізба́витися ві́чнаго муче́нія, да тебі́ всі, я́ко те́пла предста́теля, пі́сньми велича́єм.","Христу́ весь порабо́тився, преподо́бне Ни́коне, і к Нему́ все жела́ніє імі́я, і Того́ ра́ди любве́ ми́ра с жела́ньми єго́ отре́кся. Сего́ ра́ди тя всі пі́сньми ублажа́єм, Ни́коне всеблаже́нне.","Все твоє́ жела́ніє к Бо́гу му́жеськи впери́в, во ви́шніх селе́ніє сотвори́л єси́ пресла́вно. Ті́мже тя пі́сньми, блаже́нне Ни́коне, почита́єм.","А́ще і дале́че житіє́м, но близ ві́рою і любо́вію духо́внаго твоєго́ настоя́теля, і с ним вку́пі пресла́вно чудеса́ твори́ши, вку́пі же і Бо́гу предстоїте́, о всіх нас моля́щеся.","Богородичен: Му́дрости прему́дростния прия́телище била́ єси́, Пренепоро́чная, Свой бо храм от Твої́х пречи́стих крове́й, Чи́стая, созда́ти благоізво́ли на спасе́ніє на́ше."]},{"h":"Пісня 3","ps":["Ірмос: Твоя́ пісносло́вці, Богоро́дице, живи́й і незави́стний Істо́чниче, лик Себі́ совоку́пльшія, духо́вно утверди́, в боже́ственній Твоє́й сла́ві, вінце́в сла́ви сподо́би.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Лю́ди вся, тебі́ ве́дущия і заступле́нія твоєго́ ча́ющия, не пре́зри, о́тче, но, єли́ко мо́щно, предста́тельствуй, всім поле́зная прося́ моли́твами твої́ми.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Упова́ніє імі́л єси́, блаже́нне Ни́коне, і прибі́жище всіх Бо́га, Того́ моли́, мо́лим тя, о нас, любо́вію воспіва́ющих тя, приснопа́м'ятне.","Боже́ственним жела́нієм, преподо́бне Ни́коне, разжига́єм, мирську́ю красоту́ преоби́діл єси́, мона́шеськоє житіє́ возлюби́в. Ті́мже бил єси́ преподо́бним єдиножи́тель і пра́ведним.","Богородичен: Ісціле́ній Тя істо́чник, в Твою́ утро́бу вшед, показа́, Ма́ти Бо́жия Пречи́стая, мою́ у́бо ду́шу ісціли́."]},{"h":"Сідален, глас 3","ps":["Укріпля́єм Боже́ственною си́лою, преподо́бне Ни́коне, возмо́гл єси́ оскуді́ніє, от безбо́жних ага́рян би́вшеє, напо́лнити: це́рков бо но́ву і оби́тель красні́йшу па́че воздви́гл єси́. Ті́мже тя всі ублажа́єм.","Богородичен: Боже́ственная ски́нія била́ єси́ Сло́ва, єди́на Пречи́стая Ма́ти Ді́во, чистото́ю а́нгели превозше́дшая, па́че всіх мене́, персть би́вша, оскверне́на плотськи́ми прегріше́ньми, очи́сти моли́тв Твої́х боже́ственними вода́ми, подаю́щи, Чи́стая, ве́лію ми́лость."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́ во о́блаці ле́гці, при́йде Ісу́с Пребоже́ственний, Нетлі́нною Дла́нію і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Невозвра́тно ше́ствовав вводя́щий путь к небе́сному гра́ду, Ни́коне преподо́бне, іді́же наста́ви тя Святи́й Дух, оби́тель імі́я се́рдце твоє́.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Смире́ніє вознося́щеє, Ни́коне блаже́нне, в се́рдці імі́л єси́, отону́дуже тя і ми мо́лим уще́дрити смире́ніє на́ше.","Страстьми́ разли́чними коле́блемия і ві́рою притека́ющия к твоєму́ гро́бу, блаже́нне Ни́коне, святи́м твої́м хода́тайством вся посіти́ ми́лостивно к Человіколю́бцю.","Мрак страсте́й от се́рдця твоєго́ ти, преподо́бне Ни́коне, очи́стив, Христо́ва повелі́нія воі́стину світ приє́м, в пості́ просія́л єси́, умертви́в ті́ло, ду́хом же, Ни́коне, ожи́л єси́.","Богородичен: Очище́ніє всіх земни́х, ві́рою молю́ і припа́даю, Благослове́нная, моли́твами Твої́ми Судію́ і Си́на Твоєго́ ми́лостива сотвори́, я́ко да по до́лгу сла́влю Тя."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая о Боже́ственній сла́ві Твоє́й: Ти бо, неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га, і родила́ єси́ Безлі́тнаго Си́на, всім, воспіва́ющим Тя, мир подава́ющая.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","У́зький і приско́рбний путь ше́ствовал єси́, преподо́бне Ни́коне, восхожде́ньми боже́ственними се́рдця твоєго́, а́може отця́ твоєго́ наста́виша тя моли́тви.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","От гріхо́вних болі́зней м'я облегчи́ ско́рбних, і се́рдця моєго́ лю́тость утоли́, і согріше́ній оставле́ніє іспроси́, і́маши бо послу́шающа Христа́ чи́стия твоєя́ моли́тви.","Стра́сті тіле́сния воздержа́нієм, о́тче, ув'яди́в, я́ко дре́во многопло́дноє, плод чу́ден прино́сиши Бо́гу: своя́ чу́дная ісправле́нія, Ни́коне преподо́бне.","Всесві́тлий світи́льник яви́лся єси́, озаря́я пою́щия тя, Ни́коне преподо́бне. І сего́ ра́ди мо́лим тя: ві́чнаго муче́нія ізба́ви ни, пою́щия тя.","Богородичен: Ума́ моєго́ уврачу́й ізступле́ніє, Всенепоро́чная, і ісціли́ стра́сті душе́вния і уни́нія тьму отжени́, я́ко да восхвалю́ Тя по достоя́нію, Богоро́дице Всепі́тая."]},{"h":"Пісня 6","ps":["Ірмос: Боже́ственноє сіє́ і всечестно́є соверша́юще пра́зднество, богому́дрії, Богома́тере, прийді́те, рука́ми воспле́щим, от Нея́ ро́ждшагося Бо́га сла́вим.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Своє́ се́рдце, преподо́бне Ни́коне, Святи́я Тро́йці жили́ще і дом созда́л єси́. Всі, ві́рою притека́ющії к честні́й твоє́й ра́ці, просвіще́ніє, і освяще́ніє, і очище́ніє, всеблаже́нне Ни́коне, приє́млем.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Твоя́, всеблаже́нне Ни́коне, свяще́нния і всесвяти́я мо́щі, во гро́бі лежа́ще, неду́ги врачу́ють, де́монськия же полки́ прогоня́ють всегда́, ві́рним же істоча́ють ісціле́нія оби́льная, тебі́ по достоя́нію при́сно блажа́щим.","Я́ко весь Христу́ приближа́яся ясні́йши, пом'яни́ всіх, ві́рою помина́ющих тя, Ни́коне всече́стне, гріхо́в проще́нія у Христа́ прося́ і небе́снаго Ца́рствія восприя́тія.","Богородичен: Єди́на всім поможе́ніє, помози́ нам, бе́дствующим, і ру́ку пода́ждь, і к приста́нищу введи́ спасе́нія, Отрокови́це Богоблагода́тная."]},{"h":"Кондак, глас 4","ps":["Духо́вному твоєму́ настоя́телю, о́тче Ни́коне, вся́чеськи приліпи́вся і от него́ наставля́єм, во всем Христо́ві порабо́тився, мона́хов бил єси́ чинонача́льник і преподо́бних сожи́тель, с ни́миже Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Ікос","ps":["Ка́ко возмогу́ воспі́ти твоя́ ісправле́нія? Іли́ ізрещи́ труди́ твоя́, ї́миже труди́лся єси́ по отці́ твоє́м, а́ще не ти пода́си мі сло́во, недосто́йному рабу́ твоєму́? Ти бо бил єси́ по отці́ мона́хов нача́льник, с ни́миже Христа́ Бо́га моли́ непреста́нно о всіх нас."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі богому́дрії, па́че Созда́вшаго, но, о́гненноє преще́ніє му́жеськи попра́вше, ра́довахуся, пою́ще: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Вся мимотеку́щая привре́менная пристра́стія, преподо́бне Ни́коне, отрази́в, всю наде́жду к Бо́гу стяжа́л єси́, І́мже ді́йствуєши пресла́вная чудеса́.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Твоєя́ душі́ тве́рдоє і благостоя́нноє ра́зума, преподо́бне Ни́коне, ніка́коже лука́вий возмо́же соврати́ти, Бо́гу помога́ющу ті, досточу́дне.","Ми́ру умертви́вся, бу́дущую жизнь наслі́дил єси́, о́тче, ісціле́ній Боже́ственную благода́ть істоча́єши пою́щим: благослове́н Бог оте́ць на́ших.","Нельсти́вно нави́к пре́жде тебі́ би́вших оте́ць по́стничеському житію́, преподо́бне, но тіх житіє́м пожи́в, богоблаже́нне, воспіва́я: благослове́н Бог оте́ць на́ших.","Богородичен: Глаго́лом проро́чеським послі́дующе, Ді́во, Богоро́дицю, Тя іспові́дуєм: родила́ бо єси́ отроча́ всіх дре́внійшеє, Емману́їл нариця́ємоє. Єму́же зове́м: благослове́н Бог оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Му́жествовав, побіди́л єси́ стра́стная взигра́нія вся, ум просвіще́н імі́я, возмо́гл єси́, я́же ви́ді отця́ творя́ща, сія́ ді́телі іспо́лнити: ті́мже тя всі ублажа́єм, Ни́коне всеблаже́нне.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Ми́слію очище́нною, прему́дре Ни́коне, Бо́гу приближа́яся, всім всяк бив, да Христа́ приобря́щеши. Ті́мже, в небе́сния оби́телі всели́вся, преподо́бне, дерзнове́нно зри́ши Святу́ю Тро́йцю, Ю́же непреста́нно моли́ спасти́ вся, правосла́вно тя почита́ющия.","Серпо́м моли́тв, о́тче Ни́коне, стра́стная те́рнія ізсі́к і возді́лав воздержа́нія ра́лом душе́вную зе́млю, ввергл єси́ сі́мена благоче́стія в ней: ті́мже ісціле́нія плоди́ пожина́єши.","Доброді́телей тя прия́телище нариця́єм, преблаже́нне, я́ко молча́нія дру́га, і бді́нія ді́лателя, і о́браз цілому́дрія, і моли́тви жили́ще некра́домоє, і чуде́с сокро́вище, і моли́твенника о почита́ющих па́м'ять твою́, Ни́коне блаже́нне.","Богородичен: Ма́ти Бо́жия Всенепоро́чная, душі́ моєя́ я́зви ісціли́, сла́сти утоли́ пло́ті моєя́, омраче́нноє се́рдце моє́ просвіти́, і умири́ ум мой от вся́каго вре́да, і вра́жиїх м'я ізба́ви напа́стей."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Слез твої́х пролія́нієм гріхо́вний огнь погаси́л єси́, безстра́стія же во́ду ісціле́ній чи́стаго пи́ва пою́щим істоча́єши, блаже́нне Ни́коне досточу́дне.","Приспів: Преподо́бне о́тче Ни́коне, моли́ Бо́га о нас.","Ра́ка, іді́же лежи́ть свято́є ті́ло твоє́, преподо́бне Ни́коне, чуде́с благода́ть істоча́єть, просвіща́ющи на́ша ду́ші і тілеса́ і обогаща́ющи предста́теля тя те́пла і засту́пника іму́щия.","Днесь с на́ми собо́ри а́нгел і преподо́бних веселя́ться в па́м'ять твою́, блаже́нне Ни́коне, с ни́ми же помина́й ни, чту́щия тя ві́рно, досточу́дне.","Уста́ви свяще́нними твої́ми моли́твами воздвиза́ємоє на ни смуще́ніє і челові́к всіх озлобле́ніє, я́ко імі́я дерзнове́ніє ко Влади́ці і Бо́гу на́шему, Ни́коне досточу́дне.","Богородичен: О, па́че ума́ чуде́с Твої́х! Бо́жия бо Сло́ва воплоти́вшагося, Єди́наго родила́ єси́ па́че єстества́, Ма́ти Ді́во, вся́чеськая Боже́ственним Свої́м хоті́нієм му́дре держа́ща і окормля́юща."]},{"h":"Світилен","ps":["Святи́ні храм бил єси́, преподо́бне, по Боже́ственному прича́стію ра́йський граждани́н, в не́мже наслажда́єшися невозбра́нно дре́ва зна́нія і нетлі́нния сла́ви, па́м'ять творя́, Ни́коне преподо́бне, о і́же ві́рою хва́лящих тя, о́тче богому́дре.","Богородичен: Ра́дуйся, ві́рних похвало́; ра́дуйся, преподо́бних утвержде́ніє; ра́дуйся, правосла́вних сла́во; ра́дуйся, сві́те су́щих во тьмі; ра́дуйся, хра́мі пресвяти́й; ра́дуйся, Бо́жий раю́; ра́дуйся, кля́тви разріше́ніє, Благослове́нная Марі́є."]}],"notes":[]},{"u":"Канон святителю Інокентію, єпископу Іркутському","e":"Canon to St Innocent, Bishop of Irkutsk","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Істря́сшему в мо́рі мучи́тельство фарао́не, і Ізра́їля су́шею наста́вльшему, пої́м Христу́: я́ко просла́вися во ві́ки.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Ієра́рше непоро́чне, при́зри с Небесе́ і виждь, і посіти́ осіне́нієм твої́м виногра́д сей, єго́же насади́ десни́ця твоя́ во страні́ язи́ков, да просла́вим благогові́йно чудеса́ твоя́, а́ще і невозмо́жно єсть ісчи́слити я.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","На путі́ іногда́ вразумля́ше Валаа́ма осли́ця, да не і́деть проклина́ти Ізра́їля, єго́же і благослови́ прише́дий от Месопота́мії; си́це утомле́нними ко́ньми вразумле́н бисть преогорче́нний пу́тник, да возда́сть святи́телю Інноке́нтію сла́ву, є́юже обіща́ся.","Ног болі́знію, і разслабле́нієм всіх чле́нов неду́гующему, яви́лся єси́ ско́рий ціли́тель, о́тче наш Інноке́нтіє, не пре́зри у́бо і ни́ні с ві́рою притека́ющих к живоно́сним і присноціле́бним моще́м твої́м.","Богородичен: Отцю́ Собезнача́льнаго Си́на пло́тію родила́ єси́, Пренепоро́чная Ді́во, Єго́же моли́ со святи́телем, да сотвори́ть ни си́ни Своєго́ Ца́рствія, і наслі́дники обітова́нія ві́чнаго."]},{"h":"Пісня 3","ps":["Ірмос: Утверди́ наш ум і сердця́, Небеса́ сло́вом утвержде́й, во є́же пі́ти і сла́вити Тя, во спасе́ніє душ на́ших.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Купину́ втору́ю показа́л єси́, слове́сний па́стирю, єгда́ моли́твами твої́ми сохрани́л єси́ посреді́ пла́мене невреди́му святу́ю це́рков, в не́йже почива́ше не у просла́вленноє на землі́, но с Небесе́ оби́лієм чудотворе́ній я́вственно свиді́тельствованноє свя́то би́ти нетлі́нноє ті́ло твоє́.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Єди́ній ві́рі досту́пен яви́лся єси́, непоро́чне: ті́мже с преміне́нієм єстества́ уста́вов, мраз і і́ней сокри́ша чистоту́ твою́ от оче́с нечи́стих, дерзну́вших в неві́рії ви́діти тя, і́мже не дал єси́ узрі́ти сла́ви твоєя́, поуча́я ни чи́стим се́рдцем тебе́ сла́вити.","На по́мощ ско́ро прите́кл єси́ к ста́рцю, очи́ма тя́жко ви́дящему, і прикосну́вся болі́зненній главі́ єго́, яви́л єси́ на нем діла́ Бо́жия; просвіти́ у́бо і на́ша душе́вния о́чі моли́твами твої́ми, священнонача́льниче.","Богородичен: Тве́рдоє і непрело́жноє упова́ніє ві́ми Тя, Богоро́дице, єго́же держі́мся, і упова́юще мо́лимся: сохрани́ град сей, і вся гра́ди і страни́ христия́нськия от всіх бід, находя́щих челові́ком согреша́ющим, но а́біє моли́твами Твої́ми приє́млющим согріше́ній оставле́ніє."]},{"h":"Сідален, глас 3","ps":["Тако́в нам подоба́ше архієре́й, преподо́бен, незло́бив, кро́ток, отлуче́н от грі́шник, і́же пред ві́чним Архієре́єм, Ісу́с Христо́м, мо́литься ви́ну о спасе́нії ста́да своєго́: мно́го бо мо́жеть моли́тва пра́веднаго, поспішеству́єма во благо́є.","Слава: Прото́ржеся вода́ в пусти́ні, істо́чник ісціле́ній істека́єть от неістлі́нних моще́й святи́теля Інноке́нтія, ра́дость ві́чная над главо́ю єго́, єя́же да сподо́бимся і ми моли́твами єго́, в невече́рнім дні воскресе́нія.","І нині: О Тебі́, Отрокови́це, возгласи́ проро́к, глаго́ля: се врата́ восто́ка, і бу́дуть затворе́на, і нікто́же про́йдеть сквозі́ я: но Госпо́дь Бог єди́н про́йдеть, і бу́дуть врата́ затворе́на."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́, і просла́вих Твоє́ Божество́.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Ісу́с в дому́ Петро́ві прикосну́ся руці́ те́щі єго́, огне́м жего́мия, і а́біє оста́ви ю огнь; сія́ же зна́менія послі́доваша тебі́ ві́рующему чудотво́рцю, укроти́л бо єси́ огне́вицю єди́ним прикоснове́нієм бо́ку лежа́щаго на одрі́ сме́рті, но призва́вшаго тя во упова́нії жи́зні.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Ісціля́хуся іногда́ ві́рующії от нанесе́нія главотя́жей і убру́сцев Па́влових; не про́сти си́ли творя́ше Бог і твої́ма рука́ма, но́вий апо́столе, персть бо от твоєя́ свяще́нния ра́ки і єле́й от лампа́ди отверза́ють сліпотству́ющей о́чі і да́рують ісціле́ніє.","Моли́тва ві́ри спасе́ лю́ті боля́щаго, і́же і іспові́да, я́ко вра́чеве не воскреся́ть, упова́ніє же на тя, благосе́рдий о́тче, ніколи́же посрамля́єть с ві́рою призива́ющих тя во благовре́менную по́мощ.","Богородичен: Отрокови́ця неіскусому́жная ражда́єть Прови́діннаго Ду́хом от Авваку́ма, і к Рожде́нному мо́литься о душа́х на́ших, му́дре пасо́мих па́стирем, і по ісхо́ді своє́м ви́ну с на́ми в неістлі́нії свята́го тілесе́ своєго́ пребива́ющим."]},{"h":"Пісня 5","ps":["Ірмос: От но́щі неві́дінія, Богові́дінія день, во сві́ті лиця́ Твоєго́, Христе́, да возсія́єть, ко у́тру хвале́ніє Твоє́ в сердця́х на́ших.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Любо́вію погрузи́ся во струя́х упова́нія на уго́дника Бо́жия, покри́тий от глави́ до ног стру́пами і во пло́ті своє́й не обріта́яй ісціле́нія, і а́біє очи́стися от нечистоти́ болі́зненния, я́коже Неєма́н от прока́зи, погруже́нієм во Іорда́ні, по глаго́лу Єлиссе́єву.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","І́щущим тебі́ обріта́єшися гото́вий помо́щник, святи́телю Інноке́нтіє, і ско́ро подає́ши неду́гов ісціле́ніє, я́коже іногда́ жені́, болі́знующей десно́ю руко́ю, яви́лся єси́ в со́нном виді́нії і сотвори́л єси́ ю здра́ву за єди́ноє призва́ніє свята́го твоєго́ і́мене.","Тве́рдоє благода́ті позна́ніє утвержда́я во ві́рующих, научи́л єси́ нас ві́діти тя, я́ко наста́вника ми́лостиваго, благоутро́бія сокро́вище, правові́рія учи́теля, архієре́єв похвалу́, безпомо́щних засту́пника, при́сно моля́щагося о спасе́нії чад твої́х, с ві́рою к тебі́ притека́ющих.","Богородичен: Вереї́ а́дови сломи́шася, і закле́пи ві́чнії сокруши́шася Ро́ждшимся от Тебе́, Пречи́стая Ма́ти. Ті́мже мо́лим Тя: ізба́ви ни от ві́чния сме́рти хода́тайством Твої́м і всели́ ни во сві́ті Си́на Твоєго́, світ іскупле́нія ми́рові возсія́вшаго."]},{"h":"Пісня 6","ps":["Ірмос: Ри́зу мні пода́ждь сві́тлу, одія́йся сві́том, я́ко ри́зою, многоми́лостиве Христе́ Бо́же наш.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Єли́ці притека́ху к тебі́, помо́щниче те́плий, не отхожда́ху посра́млени, немощні́ї ісціля́хуся, в болі́зні діторожде́нія су́щия, от многоціле́бния благости́ні твоєя́ прийма́ху ско́роє неду́га разріше́ніє, сліпі́ї прозира́ху; посіти́ у́бо і нас, ще́дрий о́тче, твоє́ю по́мощію.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Не бу́ди неві́рен, но ві́рен, рекл єси́, о́тче, втори́цею яви́вийся от преломле́нія ноги́ лю́ті стра́ждущему, і уда́рив жезло́м в мі́сто, іді́же стоя́сте но́зі твої́, я́звою на дре́ві уврачева́л єси́ душе́вную я́зву омраче́ннаго неві́рієм, а́біє бо іспові́да би́ти тебі́ благода́тнаго врача́, воздви́гшаго єго́ от одра́ болі́зненнаго.","Непоро́чнима твої́ма рука́ма препо́дал єси́, архієре́ю Бо́жий, безсме́ртную пи́щу стра́ждущей, о чу́до! На Небесі́ приобща́яся і́стіє Невече́рняго Сві́та, вя́щше седьми́десяти літ по твоє́м успе́нії, і на землі́ явля́єшися священноді́йствитель Боже́ственних Та́їн, увіря́я па́ству твою́ в неразлу́чном пребива́нії ви́ну с притека́ющими ко твоє́й по́мощі.","Богородичен: І́стини учи́телю, наста́ви ни во і́стинній ві́рі, моля́ о спасе́нії на́шем с Пречи́стою Ді́вою Богоро́дицею Рожде́ннаго от Нея́ на спасе́ніє всего́ ми́ра."]},{"h":"Кондак, глас 4","ps":["Непоро́чности соіме́ннаго па́стиря, пропові́дника ві́ри во язи́ціх Монго́льських, сла́ву і украше́ніє Ірку́тськия па́стви, любо́вію восхва́лим всі ві́рнії: той бо єсть храни́тель страни́ сея́, і моли́твенник о душа́х на́ших."]},{"h":"Ікос","ps":["А́нгельським житіє́м возви́сился єси́, о́тче, до лицезрі́нія красоти́ несозда́нния, єя́же наслажда́яся ни́ні на Небесі́, мо́лишися о спасе́нії на́шем, нас же на землі́ науча́єши взива́ти тебі́ такова́я: Ра́дуйся, кри́не, в благорастворе́нном ю́зі процвіти́й; ра́дуйся, пе́рвенче духо́внаго синоположе́нія, от України Бо́гу посвяще́нний. Ра́дуйся, сла́во і велича́ніє гра́да Ки́єва; ра́дуйся, в земно́м учи́лищі Небе́сния му́дрости наста́вниче. Ра́дуйся, му́дрий ісполни́телю велі́ній царя́ земна́го; ра́дуйся, му́жественний подви́жниче Царя́ небе́снаго. Ра́дуйся, пропові́дниче ві́ри во язи́ціх Монго́льських; ра́дуйся, началоположи́телю до́браго священнонача́лія во страна́х Сиби́рських. Ра́дуйся, украше́ніє Ірку́тськия па́стви; ра́дуйся, благоуха́ніє пусти́ні. Ра́дуйся, о́бщаго воскресе́нія в нетлі́нії твоє́м увіри́телю; ра́дуйся, неізчерпа́ємих чуде́с істо́чниче. Ра́дуйся, храни́телю страни́ тобо́ю ізбра́нния; ра́дуйся, Інноке́нтіє, моли́твенниче о душа́х на́ших."]},{"h":"Пісня 7","ps":["Ірмос: В нача́лі зе́млю основа́вий і Небеса́ сло́вом утверди́вий, благослове́н єси́ во ві́ки, Го́споди Бо́же оте́ць на́ших.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Крі́пость і ісціле́ніє прийма́ху от тебе́, о́тче, немощству́ющії пло́тію; ско́рбнії же ду́хом і удруче́ннії печа́льми жите́йськими обріта́ху душе́вноє утіше́ніє во умиле́нном призива́нії свята́го і просла́вленнаго і́мене твоєго́, прославля́ющаго ди́внаго во святи́х Свої́х Бо́га Ізра́їлева.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","О́тче, непоро́чности соіме́нне, та́ко просла́вися світ твой пред челові́ки, я́ко ви́дяще до́брая діла́ твоя́ і чудотворе́нія мно́гая, прославля́ють чудоді́йствующаго тобо́ю, ди́внаго во святи́х Свої́х Бо́га Ізра́їлева.","Тро́їчен: Душе́вния на́ша болі́зні ісціли́, Бо́же, моли́твами просла́вленнаго от Тебе́ уго́дника, ускоря́ющаго на по́мощ умиле́нною душе́ю, тре́бующим ді́йственнаго єго́ пред Тобо́ю, Тро́йце Свята́я, заступле́нія.","Богородичен: Ум наш пліни́ в послуша́ніє ві́ри, дух і ду́шу всесоверше́ни соблюди́, і ті́ло в прише́ствіє Го́спода на́шего Ісу́са Христа́ непоро́чно сохрани́, моли́твами Твої́ми, Богороди́тельнице."]},{"h":"Пісня 8","ps":["Ірмос: Безнача́льнаго Царя́ Сла́ви, Єго́же трепе́щуть небе́сния си́ли, по́йте, свяще́нници, лю́діє, превозносі́те во вся ві́ки.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Широ́кий путь, вводя́щий в па́губу, презрі́л єси́, преподо́бне, і ті́сними врати́ вшел єси́ в небе́сноє Ца́рствіє. Отону́дуже призира́я ви́ну на призива́ющих тя с ві́рою, укріпи́ у́бо і нас понести́ благо́є і ле́гкоє і́го Креста́, да вни́дем в поко́й Бо́га благослове́ннаго.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Ангелоподо́бним житіє́м на землі́, обрі́л єси́ благода́ть ісціле́ній, і яви́лся єси́ воі́стину а́нгел храни́тель па́стви твоєя́, бо́дрственно утвержда́я ю во ві́рі многоразли́чними твої́ми чудотворе́нії, і соблюда́я в чи́стом іспові́данії отце́в Бо́га благослове́ннаго.","Христо́во благоуха́ніє яви́лся єси́, о́тче, в спаса́ємих тобо́ю от неду́гов душе́вних же і тіле́сних; ті́мже обита́телі гра́да тобо́ю ізбра́ннаго, прославля́юще святу́ю па́м'ять твою́, благословля́ють просла́вившаго тя, отце́в Бо́га благослове́ннаго.","Богородичен: Ність на́ша брань ко пло́ті і кро́ві, но к нача́лом, і ко власте́м, і к миродержи́телем тьми ві́ка сего́, к духово́м зло́би поднебе́сним; над ни́миже покажи́ ни, Влади́чице, побіди́телі, я́ко да по о́бразу непоро́чнаго па́стиря возмо́жем вся стрі́ли лука́ваго разжже́нния угаси́ти."]},{"h":"Пісня 9","ps":["Ірмос: Проявле́нноє на горі́ законополо́жнику во огні́ і купині́, Рождество́ Присноді́ви, в на́ше ві́рних спасе́ніє, пі́сньми немо́лчними велича́єм.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Апо́стол язи́ков бил єси́, о́тче, я́коже і Па́вел, ті́мже ни́ні восхище́н єси́ на висоту́ Боже́ственнаго лицезрі́нія, іді́же мо́лишися, да Бог возрасти́ть, є́же ти, му́дрий ді́лателю, насади́л і напої́л єси́.","Приспів: Святи́телю, о́тче Інноке́нтіє, моли́ Бо́га о нас.","Шлем спасе́нія восприї́м, і мече́м духо́вним препоя́сався, ізше́л єси́ на ді́ло твоє́, па́стирю ди́вний, і согради́л єси́ опло́т благоче́стія во мра́ці язи́чества. Моли́ у́бо преблага́го Бо́га, да укріпи́ть, є́же соді́ла в нас руко́ю твоє́ю.","І́менем і житіє́м непоро́чне, прийми́ хвале́бния пі́сні, любо́вію к тебі́ возноси́мия, осіня́я моли́твами твої́ми па́ству, осія́нную луча́ми добро́т твої́х, і ускоря́я на по́мощ благода́тним заступле́нієм твої́м во вре́м'я благопотре́бно.","Богородичен: Херуви́мов честні́йшая, і сла́внійшая без сравне́нія Серафи́мов, не пре́зри моле́нія раб Твої́х, но покри́й нас честни́м Твої́м покро́вом: спаси́ лю́ди, благогові́йно чту́щия па́м'ять непоро́чнаго па́стиря, і моли́твенника о гра́ді сем, ди́внаго Інноке́нтія."]},{"h":"Світилен, глас 1","ps":["Сла́ва Тебі́, Бо́гу, показа́вшему нам світ спасе́нія в житії́ і словесі́ Твоєго́ уго́дника; сла́ва Тебі́, Благода́телю, возсія́вшему просвіще́ніє і́стини в побо́рниці благоче́стія і і́стини; сла́ва Тебі́, ди́вному Щедротода́вцю, удиви́вшему ми́лості Твоя́ на ходи́вшем во сві́ті Лиця́ Твоєго́, святи́телі і чудотво́рці Інноке́нтії.","Слава, і нині, Богородичен: Світ ми́рові возсія́ в Рождестві́ Твоє́м, Пречи́стая Богоро́дице, осія́й у́бо ум наш позна́нієм Си́на Твоєго́, се́рдце уязви́ любо́вію к Боже́ственним за́повідем, укріпля́ющи ни моли́твами Твої́ми во ві́рі і благоді́ланії."]}],"notes":[]},{"u":"Канон праведному Філарету Милостивому","e":"Canon to the Righteous Philaret the Merciful","secs":[{"h":"Глас 1. Пісня 1","ps":["Ірмос: Христо́с ражда́ється — сла́віте! Христо́с с Небе́с — сря́щіте! Христо́с на землі́ — возносі́теся! По́йте Го́сподеві, вся земля́, і весе́лієм воспо́йте, лю́діє, я́ко просла́вися.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Недоумі́нним язи́ком і устна́ми хвалу́ кра́ткую принося́ твоєму́, Філаре́те, Богоподража́тельному житію́, молю́ тя: я́ко ми́лостивий, Спа́са і Бо́га ми́лость іспроси́ мі твої́ми моли́твами.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Укріпля́єма тя си́лою Ду́ха, нічто́же от до́льних преклони́ти тя возмо́же, го́ре взира́юща при́сно умо́м і вожделева́юща непрестаю́щеє улучи́ти блаже́нство.","Благода́ть Ду́ха, обрі́тши се́рдце твоє́ таково́, яково́ же уго́дно єсть єй, всели́ся в не і обита́єть в нем, неоску́дний воі́стину в нем явля́я ми́лости істо́чник, доброді́телі же вся́кия вмісти́лище, досточу́дне.","Богородичен: Безсе́менне во чре́ві прия́ла єси́ Сло́во, єди́наго от Тро́йці, Всенепоро́чная, і Сего́ по пло́ті родила́ єси́, преби́вши по рождестві́, я́коже пре́жде рождества́, Ді́ва. Сего́, я́ко Си́на Твоєго́ і Бо́га, о нас при́сно моли́."]},{"h":"Пісня 3","ps":["Ірмос: Пре́жде вік от Отця́ рожде́нному нетлі́нно Си́ну і в послі́дняя от Ді́ви воплоще́нному безсі́менно, Христу́ Бо́гу возопії́м: вознеси́й рог наш, Свят єси́, Го́споди.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Пре́жде вік от Отця́ неізрече́нно рожде́ннаго Си́на і в послі́дняя от Ді́ви воплоще́ннаго безсе́менне Христа́ подража́тель бив, по достоя́нію Христоподража́тельний глаго́лешися, Філаре́те.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Ве́ліє твоє́, блаже́нне, милосе́рдіє Го́спода возвесели́: напита́л бо єси́ а́лчуща, оді́ял єси́ на́га, стра́нна ввел єси́ в дом твой і не́мощна раде́тельне посіти́л єси́, свя́те.","Вся страна́ Пафлаго́нськая весели́ться днесь, чту́щи твою́ па́м'ять всечестну́ю, А́мнія же пелена́ми твої́ми хва́литься, вопію́щи: возвели́чихся і аз тобо́ю, свя́те Філаре́те.","Богородичен: Святі́йшая А́нгел і всея́ тва́рі вели́каго О́тчаго Сові́та А́нгела днесь ражда́єть пло́тію во спасе́ніє всіх, пою́щих Єму́ непреста́нно: Свят єси́, Го́споди."]},{"h":"Кондак, глас 4","ps":["Доброді́тельми украша́яся і стра́хом Бо́жиїм, преди́вен во всіх яви́ся Ца́рськаго гра́да, ни́щим сокро́вище бога́тства разда́в і нетлі́нно благи́х бога́тство на Небесі́х приє́м. Ті́мже всю́ду і везді́, Філаре́те, чту́щих тя помина́й, сла́во пра́ведним і похвало́."]},{"h":"Сідален, глас 8","ps":["Милостинолю́бний по́мисл восприя́в, благосострада́телен яви́лся єси́ ни́щим і нужда́ющимся, всеблаже́нне, сего́ ра́ди зва́ніє, дія́нію сро́дноє, у всіх но́сиши, ві́рно чту́щих тя. Ті́мже і Пода́тель благ ве́лією ми́лостію поми́лова і сла́вно просла́ви тя, ми́лостиве Філаре́те. Христа́ у́бо моли́ гріхо́в оставле́ніє дарова́ти пра́зднующим любо́вію святу́ю па́м'ять твою́.","Богородичен: Рождества́ Христо́ва предпра́зднственная соверша́юще, ві́рнії, торжеству́їм і досто́йні всі предусря́щим, я́коже волсви́, даронося́ще доброді́телі і пою́ще А́нгелов піснь но́вую от Ді́ви Богоотрокови́ці во Вифлеє́мі без сі́мене ражда́ющемуся Бо́гу на́шему, Єго́же сла́в'ять вся́чеськая."]},{"h":"Пісня 4","ps":["Ірмос: Жезл із ко́рене Ієссе́ова і цвіт от него́, Христе́, от Ді́ви прозя́бл єси́, із гори́, Хва́льний, приосіне́нния ча́щи прише́л єси́, вопло́щся от Неіскусому́жния, Невеще́ственний і Бо́же. Сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Храни́тель за́повідей Христо́вих бил єси́ тща́тельнійший і ісполни́тель непости́дний: Бо́га бо от се́рдця і бра́та, я́ко себе́ сама́го, возлюби́л єси́, обої́м воздава́я, всесла́вне, подоба́ющая.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","От Бо́га ізрече́нноє за преслуша́ніє Ада́му осужде́ніє: в по́ті лиця́ твоєго́ сні́си хліб твой, — обнося́ в по́мислі, смире́нні зе́млю возде́ловал єси́, я́же і подава́ше тебі́ потре́бная к житію́ оби́льні.","Ізбавле́ніє душі́ му́жа — своє́ єму́ бога́тство, глаго́леть при́тча. Но, о, му́жества! Ти отда́л єси́ послі́дняго от двою́ вола́ бли́жнему твоєму́ і сего́ ра́ди поноси́мий от супру́ги твоєя́, я́ко неразу́мний і неключи́мий, благослове́ніями той возда́л єси́.","Богородичен: Ти воі́стину ви́сшая челові́ков і А́нгел честні́йшая, Богоро́дице Ді́во, яви́лася єси́: вся́чеських бо Творця́ во чре́ві прия́ла і родила́ єси́ без сі́мене, благоволи́вшаго вочелові́читися от Тебе́ во спасе́ніє душ на́ших."]},{"h":"Пісня 5","ps":["Ірмос: Бог Сий ми́ра, Оте́ць щедро́т, Вели́каго Сові́та Твоєго́ А́нгела, мир подава́юща, посла́л єси́ нам. Тім, Богоразу́мія к сві́ту наста́вльшеся, от но́щі у́тренююще, славосло́вим Тя, Человіколю́бче.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Скор сий в раздая́нії і ми́лованії, отдава́л єси́ і послі́дняя твоя́ тре́бующим, ті́мже Єва́нгелію Христо́ву воі́стину послі́довал єси́, подража́я в милосе́рдії Отцю́ Небе́сному.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Сли́ша стропти́вая словеса́ жени́ і чад твої́х, укоря́ющих тя за милосе́рдіє, благоду́шне терпі́л єси́, всеблаже́нне, я́коже І́ов, оба́че і предре́кл єси́ їм, я́ко прови́дець, от Бо́га воздая́ніє благотворе́нія твоєго́, сла́вне.","Об'є́млеться печа́лію і го́рестію мно́гою со ча́ди супру́жниця твоя́, сли́шащи глас доі́лиці, ю́ницю свою́ зову́щия, ти же, безпеча́лен пребива́я в лише́ніях, о прося́щих тя сле́зно па́че болі́зновал єси́.","Богородичен: Спаси́тельний кров і всіх ра́дованіє, предваря́ющая ско́ро і спаса́ющая, умилосе́рдися і ни́ні, взива́єм к Тебі́, Чи́стая, о нас, призива́ющих Тя всегда́ во обстоя́нії: предста́тельства бо у Бо́га іна́го равномо́щнаго не і́мами."]},{"h":"Пісня 6","ps":["Ірмос: Із утро́би Іо́ну младе́нця ізблева́ морськи́й звір, якова́ прия́т; в Ді́ву же все́льшеєся Сло́во і плоть приє́мшеє про́йде, сохра́ншеє нетлі́нну: Єго́же, бо не пострада́ істлі́нія, Ро́ждшую сохрани́ неврежде́нну.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Благонаме́ренія твоєго́ неізмі́нность ве́ліє єсть воі́стину соверше́нство: ше́ствуя бо в житії́ путе́м ца́рським, вшел єси́ со дерзнове́нієм в Ца́рствіє непрестаю́щеє, іді́же соца́рствуєши ві́чному Царю́ Сла́ви, ми́лостиве Філаре́те.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Іно́го Авраа́ма показа́ тя ми́рові ві́ра вку́пі і человіколю́біє твоє́: боголю́бне бо ко всім благо́є расположе́ніє явля́л єси́, доброхо́тне же всім тре́бующим подава́л єси́. Сего́ ра́ди бога́тні воздая́ше тебі́ Бог в ді́ліх твої́х.","Что мі зла́то, что мі бога́тство, сла́ва же і вся земна́я мимотеку́щая? Нічто́же суть вся́ко, поне́же в нічто́ обраща́ються, многолюбе́зно же мі єди́но бога́тство Небе́сноє, всегда́ пребива́ющеє,— Філаре́та язи́к провіщава́ше.","Богородичен: Нідр не отлучи́вся Безнача́льнаго Роди́теля, Син безма́терній во утро́бу Чи́стия Ді́ви вселя́ється, без отця́ воплоща́єм, Цар пра́вди, Бог. Того́ род стра́шен, неісповеди́м і неізслі́дим."]},{"h":"Кондак, глас 3","ps":["І́стинно всеізря́дная твоя́ ку́пля зри́ться і му́дрою би́ти су́диться всі́ми благому́дрствующими: отда́л бо єси́ до́льняя і кратковре́менная, взиску́я Го́рних і ві́чних. Ті́мже і досто́йно стяжа́л єси́ ві́чную сла́ву, ми́лостиве Філаре́те."]},{"h":"Ікос","ps":["Го́спода усли́шал єси́, во Єва́нгелії законополага́юща: продаді́те імі́нія ва́ша і даді́те ми́лостиню, сотворі́те себі́ влага́лища неветша́юща, сокро́вище неоскудева́ющеє на Небесі́х, іді́же ні тать кра́деть, ні моль істліва́єть. Сего́ Боже́ственнаго і к соверше́нству возводя́щаго законоположе́нія ре́вностний ісполни́тель бил єси́: про́дал бо єси́ вся і дал єси́ ми́лостиню, сотвори́л єси́ себе́ влага́лища нетлі́нна і сокро́виществовал єси́ сокро́вище на Небесі́х некра́домоє. Сего́ ра́ди і блаже́нствуєши со благослове́нними Отця́ Небе́снаго, я́ко наслі́дник от сложе́нія ми́ра угото́ваннаго Ца́рствія, ми́лостиве Філаре́те."]},{"h":"Пісня 7","ps":["Ірмос: О́троци, благоче́стію совоспита́ни, злочести́ваго велі́нія небре́гше, о́гненнаго преще́нія не убоя́шася, но, посреди́ пла́мене стоя́ще, поя́ху: отце́в Бо́же, благослове́н єси́.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","В тебі́, не то́чію не ізме́ншемся от дия́воля нападе́нія, но па́че в доброді́телі укре́пльшемся, Філаре́те, воі́стину Христо́с просла́вися, враг же, іскуша́яй тя, постиді́ся. Сего́ ра́ди взива́л єси́: Бо́же, благослове́н єси́.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","На предложе́ніє твоє́, блаже́нне, призира́єть Христо́с і воздає́ть ті мно́гими благи́ми пе́рвіє, по іскуше́нії же і бо́льшими. Сего́ ра́ди і взива́л єси́: Бо́же, благослове́н єси́.","Нрав твой страннолюби́вому нра́ву Авраа́мову подо́биться, блаже́нне Філаре́те: ти бо, я́коже той, пу́тники не оставля́л єси́ мимоіти́, но сам во срі́теніє їм текл єси́, взива́я: Бо́же, благослове́н єси́.","Богородичен: От всіх приє́млющи проше́нія, Богоро́дице, моли́ся Си́ну Твоєму́ і Бо́гу от всіх зол ізба́витися нам, чту́щим Тя і ко Го́споду взива́ющим: отце́в Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Чу́да преєсте́ственнаго росода́тельная ізобрази́ пещ о́браз: не бо, я́же прия́т, пали́ть ю́ния, я́ко ніже́ огнь Божества́ — Ді́ви, в Ню́же вни́де утро́бу. Тім, воспіва́юще, воспої́м: да благослови́ть твар вся Го́спода і превозно́сить во вся ві́ки.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Гостеприї́мство твоє́, ми́лостиве, чу́да бисть воі́стину вино́вно, єгда́ благоприя́тен показа́ся невестоводи́телем царя́ і самому́ царю́ Христоіме́нному вну́ки твоєя́ о́браз. Сего́ ра́ди і жре́бій благи́й устро́їся єй ку́пно с тобо́ю Бо́жиїм смотре́нієм, вся пра́в'ящим.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Глаго́ли му́дрости, о́тче, прия́л єси́ во глубину́ душі́ твоєя́, сего́ ра́ди от блага́го сокро́вища се́рдця твоєго́ благи́я плоди́ ізне́сл єси́. Ті́мже восприя́л єси́ блага́я і в животі́ твоє́м, бив сро́дник царе́в сла́вний і бога́тий, по успе́нії же твоє́м Ца́рствіє Небе́сноє наслі́довал єси́.","Вели́ка і́стинно показа́ тя ра́зума твоєго́ і́стина, блаже́нне, а не от челові́к сла́ва і сві́тлость привре́меннаго досто́їнства, я́ко при́сно пребива́ющих взиску́я, к тім вся́чеськи стреми́лся єси́. Ті́мже тя восхваля́єм, Філаре́те Богому́дре.","Богородичен: Стра́ннаго соби́тія о́браз показа́ купина́, неопа́льно горя́щая дре́вле на горі́ Сина́ї, та́їнство рождества́ Твоєго́ прообразу́ющи, Пренепоро́чная Ді́во: огнь бо в Тебі́ Божества́ все́льшійся неврежде́нну Тя сохрани́. Сего́ ра́ди Тя поє́м во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Та́їнство стра́нноє ви́жу і пресла́вноє: Не́бо — верте́п; престо́л Херуви́мський — Ді́ву; я́сли — вмісти́лище, в ни́хже возлеже́ Невмісти́мий — Христо́с Бог, Єго́же, воспіва́юще, велича́єм.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Чудеси́ Бог прославля́єть і кончи́ну твою́, Філаре́те: прикоснове́нієм бо ко гро́бу твоєму́ прогоня́ється де́мон, стужа́яй от рожде́нія ни́щему, всегда́ тобо́ю ми́луємому, сострада́тельне.","Приспів: Святи́й пра́ведний Філаре́те, моли́ Бо́га о нас.","Предрека́єши, я́ко і́ний Іа́ков, ча́дом твої́м іму́щая би́ти, ку́пно же і законополага́єши їм ми́лостивим би́ти, я́коже ти; ї́хже і благослов'я́, пре́дал єси́ в ру́ці Бо́жії святу́ю твою́ ду́шу, блаже́нне.","Прийми́ от нас, Філаре́те, я́ко досто́йную, сію́ піснь малобде́нную, я́коже і Христо́с прия́т вдови́ці дві ле́пті, і іспроси́ нам, всеблаже́нне, у Христа́ Бо́га на́шего ве́лію і бога́тую ми́лость.","Богородичен: Спасе́ся вся твар Рождество́м Твої́м, і от'я́ Госпо́дь плач і рида́ніє, і вся́ку сле́зу от вся́каго лиця́, Чи́стая Богоро́дице, Всенепоро́чная, ті́мже досто́йно ублажа́єм Тя, А́нгелов і челові́ков Ра́досте."]},{"h":"Світилен","ps":["Філаре́та па́м'ять ми́лостиваго, ві́рнії, почти́м досто́йно, я́ко долго́в оставле́ніє і разріше́ніє согріше́ній того́ моли́твами улуча́єм всі."]}],"notes":[]},{"u":"Канон преподобному Саві, ігумену Сторожевському, Звенигородському","e":"Canon to St Sabbas, Abbot of Storozhi, of Zvenigorod","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Наста́ви м'я, Го́споди Бо́же мой, да возмогу́ благоче́стно уго́дника Твоєго́, преподо́бнаго Са́вви, сла́вноє і честно́є восхвали́ти торжество́.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Му́жеськи подвиза́лся єси́ і, зарю́ духо́вную восприє́м, взя́лся єси́ к висоті́ небе́сній, і ни́ні со а́нгели прославля́єшися.","Ору́жієм креста́ огражда́яся, преподо́бне, всю си́лу проти́внаго побіди́л єси́ і до конця́ сего́ без ві́сти сотвори́л єси́.","Богородичен: Пресу́щноє Сло́во, существо́ на́ше приє́м от чи́стих крове́й Твої́х, богосоді́ла нас, тлі́нія ізба́вив, Чи́стая: сего́ ра́ди Тя при́сно сла́вим."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Молча́нієм язи́к обузда́л єси́ і нем'яте́жним житіє́м во пло́ті а́нгельськи, о́тче, пожи́л єси́.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Воі́стину благи́я жи́зні сподо́бился єси́, преподо́бне, чистото́ю і поще́нієм сію́ обрі́ть. І ни́ні со безпло́тними вопіє́ши: ність свят, па́че Тебі́, Го́споди.","Трисія́нним Сві́том озаре́н, і благода́ть Ду́ха Свята́го всели́ся в тя, преподо́бне, возлю́бльши чи́стую твою́ ду́шу, і непреста́нно вопіє́ши: ність свят, па́че Тебі́, Го́споди.","Богородичен: Разумі́ти рождества́ Твоєго́, Чи́стая, неізглаго́ланную глубину́ недоумі́єть ум челові́ч: Бог бо, істощи́в Себе́ за милосе́рдіє во утро́бі Твоє́й, всего́ м'я обнови́."]},{"h":"Сідален, глас 4","ps":["Мраз нощни́й претерпі́л єси́, і тяготу́ ва́ра дневна́го поне́сл єси́, і сих ра́ди ві́чноє наслажде́ніє і пи́щу присноживу́щую восприя́л єси́, Христо́в уго́дниче, блаже́нне Са́вво: моли́ спасти́ся душа́м на́шим.","Богородичен: Чи́стая, Всенепоро́чная і Неіскусому́жная, Я́же єди́на Безлі́тнаго Си́на і Сло́ва Бо́жия в лі́то ро́ждши, Сего́ со святи́ми і честни́ми патріа́рхи, му́ченики, проро́ки і преподо́бними моли́ дарова́ти нам очище́ніє і ве́лію ми́лость."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, честна́я Це́рков боголі́пно поє́ть, взива́ющи, от сми́сла чи́ста, о Го́споді пра́зднующи.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Безмі́рноє смире́ніє возлюби́в, своєя́ ми́слі зри́тельноє очи́стил єси́ і ни́ні, в ра́йських селе́ніїх водворя́яся, вопіє́ши: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Сле́зними пото́ки, преподо́бне, зе́млю се́рдця твоєго́ напої́л єси́, предстоя́ в моли́тві неколе́блен, Творцю́ всіх взива́л єси́: сла́ва си́лі Твоє́й, Го́споди.","Не забу́ди ста́да твоєго́, преподо́бне, є́же му́дре собра́л єси́ і в жи́зні сей упа́сл єси́ благоче́стно: потщи́ся, о́тче наш Са́вво, ввести́ во огра́ду небе́сную.","Богородичен: Чистоти́ жили́ще, селе́ніє Влади́ки всіх і проро́ков всіх сбитіє́, Богора́дованная Чи́стая, пою́щия Тя уще́дри."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті ду́ші любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, і́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Бо́дренними бді́нії, блаже́нне, і ча́стими воздиха́нії, Благода́ть Ду́ха возрасте́ в тебі́, о́тче, і сла́вна тя, Са́вво, показа́.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Влади́чне смире́ніє восприї́м, во́ду почерпа́я, на ра́міх свої́х носи́ти ізво́лил єси́: нача́льника трудополо́жна во всем себі́ показа́л єси́.","Преблаже́нне, богоприя́тне о́тче наш Са́вво, непреста́нно ста́до твоє́ вопіє́ть ті: моли́твами твої́ми ко Го́споду спаси́ ни, мо́лимся.","Богородичен: По рожде́нії стра́шнім пребила́ єси́ Ді́ва, я́коже пре́жде. Бог бі рожде́йся, устроя́яй вся во́лею, Безневі́стная Марі́є Богоблагода́тная."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре, воздвиза́ємоє зря напа́стей бу́рею, к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: возведи́ от тлі живо́т мой, Многоми́лостиве.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Страда́нії по́двиг твої́х, преблаже́нне, клас боже́ственний возрасти́л єси́ і пита́єши благоче́стно восхваля́ющия тя, Са́вво преподо́бне, о́тче наш.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Кня́зя проше́ніє, о́тче, со тща́нієм ісполня́я, храм Богома́тере воздви́гл єси́, в не́мже пра́здничною ра́достію мона́хов мно́жества веселя́ться, па́м'ять твою́ прославля́юще.","Ка́плями по́тов твої́х, преподо́бне, враго́в ополче́нія попра́л єси́ і дости́гл єси́ а́нгельськія невеще́ственния ли́ки.","Богородичен: Всеблага́я Влади́чице, я́же преблага́го Бо́га пло́тію ро́ждши, озло́бленноє страстьми́ моє́ се́рдце очи́сти, да ві́рою і любо́вію велича́ю Тя."]},{"h":"Кондак, глас 2","ps":["Госпо́днім жела́нієм распали́вся, стра́сті плотські́я воздержа́нієм оттря́с, Боже́ственнаго сві́та незаходи́моє світи́ло яви́лся єси́, чуде́с луча́ми всіх просвіща́єши, притека́ющих к ра́ці моще́й твої́х, Са́вво преподо́бне, о́тче наш."]},{"h":"Ікос","ps":["Всеси́льноє Ду́ха Свята́го ді́йство богови́дно в тя всели́ся, і боголі́пними манове́нії благоте́чні іди́й ко горі́, іді́же хоті́л єси́ оби́тель воздви́гнути, і, я́коже небе́сний рай, благово́нними насажде́н цвіти́, сію́ обрі́т, всели́лся єси́ і храм Богома́тере чу́ден воздви́гл єси́, мона́хов мно́жество собра́л єси́, і сія́, доброді́тельними дія́нії сві́тло блиста́ющия, воздержа́нії му́дростная вообра́ж; і ни́ні, в па́м'ять твою́ соше́дшеся, вопіє́м ті: моли́ о нас, Са́вво преподо́бне, о́тче наш."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ соді́ла а́нгел преподо́бним отроко́м, халде́ї же опаля́ющеє велі́ніє Бо́жиє, мучи́теля увіща́ вопи́ти: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Пучи́ною слез твої́х, пребога́те, злонача́льнаго змі́я потопи́л єси́, я́ко побідоно́сець ізря́ден к небе́сним возлеті́л єси́, непреста́нно вопіє́ши: благослове́н Бог оте́ць на́ших.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Житіє́ незло́биво імі́л єси́, і непоро́чно, і укра́шено по́ти страда́нія, прехва́льне, Боже́ственнаго світоли́тія іспо́лнився, взива́л єси́: благослове́н Бог оте́ць на́ших.","Хва́литься, преподо́бне, град твой, я́ко вінце́м ца́рським обложи́ся, імі́я мо́щі твоя́ в себі́, я́ко добра́ граждани́на от Бо́га прия́л єсть.","Богородичен: Препі́тая Ді́во, препі́таго Бо́га ро́ждшая, пою́щия Тя прича́стники покажи́ Сві́та і ізба́ви геє́нни огня́ і вся́каго вре́да вра́жия моли́твами Твої́ми."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́ і пра́веднаго же́ртву водо́ю попали́л єси́: вся бо твори́ши, Христе́, то́кмо є́же хоті́ти. Тя превозно́сим во вся ві́ки.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Мудрова́ніє плотсько́є умертви́л єси́, че́сти і імі́нія совле́клся єси́, от землі́ к небе́сним взи́ти тща́ся і вся пі́ти науча́я: Го́спода по́йте і превозносі́те єго́ во ві́ки.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Се́рдця твоєго́ бразди́, о́тче Са́вво, му́дре возді́лал єси́, сле́зними ту́чами сія́ напої́л єси́ і благоуха́нно ми́ро прине́слся єси́ Христу́, Єму́же вопіє́ши: Го́спода по́йте і превозносі́те Єго́ во ві́ки.","Христу́ принося́, блаже́нне, поще́нія, і сле́зи, і непоро́чную моли́тву, ри́зную лі́поту і м'я́гкия оде́жди власяни́ми ру́би преміни́л єси́, сим показу́я глубоча́йшеє смире́ніє.","Богородичен: Ізба́вльшеся пе́рвия кля́тви Рождество́м Твої́м, всеблагослове́нная Отрокови́це Богора́дованная, Гавриї́лов тебі́ глас возсила́єм: ра́дуйся, вино́вная всіх спасе́нія."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га челові́ком невозмо́жно ви́діти, на Него́же не смі́ють чи́ни а́нгельстії взира́ти; Тобо́ю бо, Всечи́стая, яви́ся челові́ком Сло́во воплоще́нно, Єго́же велича́юще, с небе́сними во́ї, Тя ублажа́єм.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Ви́діти сла́ву Вседержи́теля жела́я, обнови́л єси́ душі́ крі́пость і сла́вою обогати́лся єси́ небе́сною.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Честно́є украше́ніє благода́ті, о́тче преподо́бне Са́вво, іспроси́ нам во бранеіх крі́пость і здра́віє тілесе́, я́ко да непреста́нно тя велича́єм.","Чи́ни а́нгельстії тебі́, о́тче, сріто́ша, і пра́ведних собо́ри возвесели́шася, і от вседержи́тельния десни́ці Влади́чни вінча́лся єси́, ті́мже тя досто́йно велича́єм.","Богородичен: Сві́том Твої́м м'я, Богора́дованная в жена́х Ді́во, просвіти́, молю́ся, і огня́ ві́чнаго ізба́ви м'я, я́ко да велича́ю Тя і по до́лгу да воспою́ вели́чія Твоя́."]},{"h":"Світилен","ps":["По́мислом лу́чшим стра́сті удержа́в, і де́монов свирі́пства низложи́л єси́. І ни́ні со дерзнове́нієм предстоя́ Христу́, моли́ся о ста́ді твоє́м, о́тче наш.","Богородичен: По Бо́зі на Тя упова́єм, Пречи́стая, із Тебе́ проше́дшему сраспина́ємі Христу́, Твої́ми к Нему́ мольба́ми неврежде́нни до конця́ ни сохрани́."]}],"notes":[]},{"u":"Канон преподобному Саві Освяченому","e":"Canon to St Sabbas the Sanctified","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Колесницегони́теля фарао́ня погрузи́ чудотворя́й іногда́ Моїсе́йський жезл, крестообра́зно порази́в і разділи́в мо́ре, Ізра́їля же біглеця́, пішехо́дця спасе́, піснь Бо́гові воспіва́юща.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Світозаре́нієм Свята́го Ду́ха, Са́вво, озари́ благоче́стною любо́вію пі́сньми восхваля́ющия тя, по́стников похвалу́, мона́шествующих сла́ву, пусти́ні украси́теля, благоче́стія учи́теля.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Всю любо́в к Бо́гу возложи́в от ю́ности, і к Нему́, ра́дуяся, все твоє́ жела́ніє імі́я, пло́ті движе́нія і страсте́й нахо́ди воздержа́нієм умертви́л єси́, Са́вво богоно́се всехва́льне.","Побіди́в плодо́м, сокрове́ннаго змі́я попра́л єси́ і того́ сі́ті легко́ премину́л єси́, богоче́стія крили́ впери́вся, о́тче; жизнь же, ра́дуяся, об'я́л єси́ от са́да кре́стнаго.","Просвіща́єм Сві́том благода́ті, во огнь вшел єси́, я́коже тріє́ о́троци преби́л єси́ неопале́н, Бо́гу тя сохра́ншу і явля́ющу всім бу́дущеє тебі́ преспі́яніє, по́сліжде, о́тче, і соверше́ніє.","Богородичен: Неуде́ржними на нас смерть стремле́ньми я́ться, но, Твоєму́ Рождеству́ прибли́жившися, поги́бе і, прирази́вшися, упраздни́ся, Богоро́дице Ді́во, Жизнь бо воі́стину присносу́щную воплоти́вшуюся родила́ єси́."]},{"h":"Пісня 3","ps":["Ірмос: Утвержде́й в нача́лі небеса́ ра́зумом і зе́млю на вода́х основа́вий, на ка́мені м'я, Христе́, за́повідей Твої́х утверди́, я́ко ність свят, па́че Тебе́, Єди́не Человіколю́бче.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Ум влади́ку над страстьми́, всебога́те, поста́вив, пода́тель пра́вди показа́лся єси́, лу́чшему бо я́ві ху́ждшеє повину́л єси́. Ті́мже, я́ко фі́нікс, о́тче, в пусти́нях процві́л єси́.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Послі́довати разумі́в стопа́м Влади́ки, пресе́льник оте́чества бил єси́ і, в пусти́ні обита́я, побі́ду воздви́гл єси́ на противобо́рния, Боже́ственною си́лою укріпля́єм.","Тве́рдостію ра́зума, всеблаже́нне, укріпля́єм, разли́чная вра́жия кова́рства обличи́л єси́, му́дре, і всім яви́л єси́ і горди́ню о́наго возви́шенную низложи́л єси́.","Свяще́нна тя душе́ю і простоти́ ізволе́нія доброді́тельми укра́шена ви́дя, світлі́йшая звізда́ Євфи́мій прия́т, проро́чеськи віща́я твою́, всеблаже́нне, сві́тлость.","Богородичен: Спаси́тельнаго нас ра́ди Сло́ва строє́нія сві́тлая Ти, Ма́ти Ді́во, двер позна́лася єси́ воі́стину: Ти бо нам ввела́ єси́ у́мную лучу́ Пребоже́ственнаго Божества́."]},{"h":"Сідален, глас 8","ps":["Земна́я вся оста́вив, в ми́рі сий тіле́сно, ду́хом бил єси́ а́нгелом соприча́стник: настоя́щия бо стра́сті тіле́сния умертви́в, Тро́йці показа́лся єси́ служи́тель, блаже́нне. Ті́мже і неду́гующих врачу́єши стра́сті і сло́вом ду́хи отго́ниши благода́тію, богоно́се о́тче наш; моли́ся Христу́ Бо́гу прегріше́ній оставле́нію дарова́тися пра́зднующим любо́вію святу́ю па́м'ять твою́.","Слава: Молви́ жите́йськія оста́вив, крест твой на ра́мена взем, всего́ возложи́л єси́ тебі́ Бо́гу, пло́ті же і ми́ра вні бив, Ду́ху бил єси́ Свято́му собесі́дник. Ті́мже і к ре́вности лю́ди воздвиза́я, гра́ди істощи́л єси́ і пусти́ні гра́ди сотвори́л єси́, богоно́се о́тче наш, моли́ Христа́ Бо́га прегріше́ній оставле́нію дарова́тися пра́зднующим любо́вію святу́ю па́м'ять твою́.","Богородичен: Я́ко Всенепоро́чная Неві́сто Творця́, я́ко Неіскусому́жная Ма́ти Ізба́вителя, прия́телище я́ко су́щи Уті́шителя, Всепі́тая, беззако́нію м'я су́ща скве́рноє оби́телище і де́моном ігра́лище в ра́зумі би́вша, потщи́ся і тіх злоді́йствія м'я ізба́вити і сві́тлоє жили́ще доброді́телей соверши́, Світоно́сная, Нетлі́нная, отжени́ о́блак страсте́й і ви́шняго прича́стія сподо́би і Сві́та Невече́рняго моли́твами Твої́ми."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, Ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Душе́вноє очища́я устроє́ніє і разширя́я Боже́ственними виді́нії, вмі́стну сію́ воі́стину Боже́ственних дарова́ній соді́лал єси́, богоблаже́нне: возложе́нієм же рук твої́х немощству́ющия ісціли́л єси́, подража́тель Влади́ки бив.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","І́же на тя, о́тче, лю́ті разсвирі́пів, поглоти́ся, я́ко Дафа́н окая́нний, і, я́ко Авиро́н, потреби́вся: тя бо неви́димо Боже́ственная храня́ше благода́ть, мно́гих промишля́ющи спасе́ніє, всеблаже́нне, сла́вний Са́вво богому́дре.","Зако́ном Бо́жиїм наказа́в, богоглаго́ливе, чу́вства, к разумі́нію безтіле́сних і ми́сленних твою́ худо́жную упра́вил єси́ мисль, проходя́ неосла́бно от сла́ви в сла́ву, от си́ли, о́тче, в си́лу.","Благоді́тельствовати єдиноплеме́нния предложи́в, в пусти́ні гра́ди созда́л єси́ боголі́пни і душеполе́зни, і в землі́ жа́ждущей істо́чники вод ізве́л єси́, і ту́чі с небесе́ пресла́вно, богому́дре, в безво́дних се́ліх низве́л єси́.","Богородичен: Новоцві́тний безсме́ртія рай і красе́н воі́стину показа́лася єси́, дре́во жи́зні, в Тебі́ насажде́нноє, богонача́льнійше чревонося́щи і ражда́ющи, всім іска́пающеє спаси́тельния наде́жди, ві́рно Богоро́дицю му́дрствующим Тя."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма окая́ннаго? Но обрати́ м'я, і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Неукло́нною ми́слію к твоєму́ Жела́ємому простира́яся, от Него́ благода́ть велича́йших чуде́с незави́стну прия́л єси́, о́тче, і ві́рно приходя́щия сострада́тельно уврачева́л єси́, преподо́бне.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Плотськи́х тя́жестей дебельство́ отложи́в, сосу́д богоді́ланен ізбра́н бил єси́ Свята́го, чу́дне, Ду́ха, оша́янієм сні́дей, і моли́твою, і терпі́нієм, і смиреному́дрієм украша́єм.","Пропові́дник Боже́ственних догма́ть велегла́снійший рукоположе́н єси́, собо́ров, о́тче, святи́х соо́бщник бил єси́, цари́ умудря́я, і́миже я́ві, благода́тію Боже́ственною огражда́єм, яви́лся єси́, блаже́нне.","От Бо́га да́вшаяся благода́ть тебі́, богодохнове́нне, провозгласи́ся, раздаде́ся всім бо вселе́нния конці́, я́ві творя́щи боголі́пно показа́нія чуде́с Боже́ственноє ді́йство.","Богородичен: Ві́рних Предста́тельниця, стіна́ неразруши́ма благохва́лящих Тя, я́ко всему́ ро́ду челові́чеському я́вльшеєся спасе́ніє, Бо́га ро́ждши тіле́сні я́вльшася, ду́шу мою́ спаси́, Пречи́стая."]},{"h":"Пісня 6","ps":["Ірмос: Очи́сти м'я, Спа́се, мно́га бо беззако́нія моя́, і із глубини́ зол возведи́, молю́ся, к Тебі́ бо возопи́х, і усли́ши м'я, Бо́же спасе́нія моєго́.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Любо́в к Бо́гу і бли́жнему стяжа́в, зако́на і проро́ков ісполня́я глави́зну, прейму́щую бо всіх несосу́дно доброді́тель, о́тче, іспра́вил єси́.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Равноа́нгельноє на землі́ ти жи́тельство стяжа́л єси́, равноа́нгельну же честь Христо́с тебі́ дарова́, святи́х чи́ни спутьше́ствующия душі́ твоє́й посла́в.","Прему́дрости поро́д яви́вся, нача́ло прему́дрости возжелі́л єси́ — страх Бо́жий, і́мже укріпля́єм, к соверше́нію вмі́стному челові́ком, о́тче, дости́гл єси́.","Богородичен: Спа́са і Ізба́вителя, Бо́га всіх і Го́спода ро́ждши, нам пло́тію приобщи́вшася, спаса́й, Пречи́стая, призива́ющия Тя от бід, Влади́чице."]},{"h":"Кондак, глас 8","ps":["Я́ко от младе́нства Бо́гу же́ртва непоро́чная прине́слся єси́ доброді́телію, Са́вво блаже́нне, садоді́латель бив благоче́стія; ті́мже бил єси́ преподо́бних удобре́ніє, граждани́н же пусти́нний достохва́лен. Ті́мже зове́м ті: ра́дуйся, Са́вво пребога́те."]},{"h":"Ікос","ps":["О, отце́во верхо́вниче і преподо́бних красото́, по́стников ко Христу́ дерзнове́ніє, пусти́нний граждани́не і садоді́лателю! Ка́ко воспою́ твоє́ житіє́, преподо́бне? Блиста́єши бо конце́м, я́ко со́лнце. Тім вопію́ ті: ра́дуйся, кра́сная каппадо́ков сла́во; ра́дуйся, честно́є вселе́нния зна́меніє; ра́дуйся, пусти́ні добрі́йшеє прозябе́ніє; ра́дуйся, пра́ведних боже́ственноє наслажде́ніє; ра́дуйся, я́ко презрі́л єси́ теку́щая і тлі́нная; ра́дуйся, я́ко на небесі́х со а́нгели обита́єши; ра́дуйся, мона́шествующих ісправле́ніє і пра́вило; ра́дуйся, ліня́щихся к Бо́гу воздви́женіє; ра́дуйся, істо́чниче чуде́с богото́чний: ра́дуйся, честни́й Ду́ха орга́не; ра́дуйся, і́мже украси́ся восто́к; ра́дуйся, і́мже за́падная сія́ють; ра́дуйся, Са́вво пребога́те."]},{"h":"Пісня 7","ps":["Ірмос: Бо́жия снисхожде́нія огнь устиді́ся во Вавило́ні іногда́, сего́ ра́ди о́троци в пещі́, ра́дованною ного́ю, я́ко во цві́тниці, лику́юще поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Отложи́л єси́ привре́менная, ві́чними возме́здився, і со а́нгели лику́єши, я́ко а́нгельськоє пожи́в житіє́. С ни́миже і піл єси́: благослове́н Бог оте́ць на́ших.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Вопіє́ть благода́рно ко Го́споду твоя́ вели́кая і всечестна́я Ла́вра, жи́теля, і зижди́теля, і граждани́на тя предлага́ющи, му́дре, і хва́лящися зове́ть: благослове́н Бог оте́ць на́ших.","Непреста́нно моли́ Го́спода, Са́вво богому́дре, о па́стві твоє́й, прилі́жно же іспроси́ твої́м трудо́м ві́чновати при́сно плодонося́щим і любо́вію зову́щим: благослове́н Бог оте́ць на́ших.","Богородичен: Неві́стник пречи́ст па́че словесе́ Сло́ва воплоще́нія, і черто́г, і престо́л пра́вая му́дрствующії Тя імену́єм і, ра́дующеся, Твоєму́ Си́ну зове́м: благослове́н Бог оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци, благослові́те, свяще́нници, воспо́йте, лю́діє, превозносі́те во вся ві́ки.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","С весе́лієм, преподо́бне, святи́х чи́ни чисті́йшей твоє́й душі́ предтеку́ть на мі́сто отра́дно в сві́тлая селе́нія, іді́же пра́ведних ли́ци веселя́ться. С ни́миже ни́ні поє́ши: свяще́нници, воспо́йте, лю́діє, превозносі́те Христа́ во ві́ки.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Стра́нна твоя́ чудеса́: зві́ри бо укроти́л єси́, ути́шив страсте́й во́лни, предглаго́леши бу́дущая проро́чеським да́ром, полки́ де́монськия прогоня́я, язви́ши благомо́щними бді́нії же і моли́твами, і поще́ньми, і креста́ си́лою непобіди́мою, богоно́се.","І́же Моїсе́ю пе́рвіє от столпа́ віща́вий, столп от землі́ до небесе́ всесві́тел просте́рт тебі́ показа́, іді́же ни́ні лежи́ть терпіли́воє твоє́ і многострада́льноє ті́ло. Єму́же, ві́рою предстоя́ще, благоче́стно поє́м: лю́діє, превозносі́те Христа́ во ві́ки.","Ра́достно па́м'ять твоя́ соверша́ється, всехва́льне: в радостотво́рную бо оді́ялся єси́ доброді́тель, і́стинную ри́зу спасе́нія, і чи́стую, і світови́дную весе́лія оде́жду, в не́йже ни́ні, красу́яся, поє́ши непреста́нно: свяще́нници, воспо́йте, лю́діє, превозносі́те Христа́ во ві́ки.","Богородичен: Неіскусобра́чно родила́ єси́, Ді́ва преби́вши, і стра́нним Рождество́м Твої́м совокупи́ла єси́ вся, вре́менную брань і да́льнеє разстоя́ніє разруши́вши, Христа́, ми́ра да́теля, нося́щи в ні́дріх Твої́х. Єго́же ві́рно поє́м і превозно́сим во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє небе́с. Тім Тя, Богоро́дицю, а́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Благоуха́єть твоя́ ра́ка духо́вноє благово́ніє, бога́тно веселя́щи твоя́ си́ни, тя обстоя́щия і́скренно, помина́ющия, преподо́бне, а́нгельськоє твоє́ пребива́ніє, і тебі́ да́нную сві́тлость, і сла́ву, і присносу́щную красоту́.","Приспів: Преподо́бне о́тче Са́вво, моли́ Бо́га о нас.","Прото́ржеся в пусти́ні вода́, і земля́ жа́ждущая в бла́то бисть, моли́твами претво́ршися, о́тче, твої́ми: по́стничестії бо полки́ сію́ населя́ють, я́ко рі́чну, страна́ Іорда́нова процвіте́, я́ко крин, напая́єма твої́ми слеза́ми.","Сві́тлость святи́х на небесі́х я́ко пра́веднику тебі́ возсія́, о́тче, Христа́ бо пра́вду і́стинную проявле́нно возлюби́л єси́; Єго́же жи́тельству послі́дуя, всеблаже́нне, уподо́бився Сего́ живоно́сній, я́ко мо́щно бі, святи́ні.","Бога́тним, богоно́се, сія́я Сві́том і ли́ки а́нгельськия ви́дя, світови́дни обходя́щия Тро́їчеський Світ і приє́млющия благода́тію боговиді́нія лучи́, не преста́й моля́ оставле́нія гріхо́в сподо́битися пою́щим тя.","Богородичен: Я́ко всіх преви́шши земноро́дних несравне́нними, Чи́стая, пе́рвенстви: Бо́га бо, всіх тва́рей Творця́, во утро́бу Твою́ вмісти́ла єси́. Того́ моли́ я́ко Ми́лостива єдиномишле́ніє, мир, благостоя́ніє ти́хоє Це́рквам дарова́ти."]},{"h":"Світилен","ps":["Пусти́ню град сотвори́л єси́ любому́дрими нра́ви, отце́в красото́, Са́вво, о́тче богому́дре, і сію́ соверши́л єси́ ми́сленний рай, цвіту́щ цві́ти боже́ственними, єдинонра́вних мно́жества, досто́йно соверша́ющих твою́ честну́ю па́м'ять.","Богородичен: Я́ко іму́щи сострада́тельноє і ми́лость ве́лію, при́зри, Всепі́тая Богоро́дице Ді́во, на моє́ смире́ніє і страсте́й молву́, і собла́знов житія́ разори́, Отрокови́це, і огня́ геє́нськаго ізба́ви м'я моли́твами Твої́ми."]}],"notes":[]},{"u":"Канон преподобному Максиму Сповіднику","e":"Canon to St Maximus the Confessor","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Пої́м Го́сподеві, прове́дшему лю́ди Своя́ сквозі́ Чермно́є мо́ре, я́ко Єди́н сла́вно просла́вися.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Всю мні богодухнове́нную от медото́чнаго і сла́дкаго твоєго́ іска́пай язи́ка, боже́ственний Макси́ме, благода́ть Ду́ха.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Огнь горя́щ яви́лся єси́ на є́ресі, блаже́нне: я́ко бо тро́стіє, сія́ ізнури́л єси́ ре́вностію Ду́ха.","Безслове́сноє предложи́ся от злочести́війшаго проізволе́нія єдиново́льноє уче́ніє, словеси́ же твої́ми, о́тче, обличи́ся.","Богородичен: Весь жела́ніє, із утро́би Твоєя́, Богоневі́сто, благоізво́ливий роди́тися, і Сла́дость єсть, і Світ незаходи́мий."]},{"h":"Пісня 3","ps":["Ірмос: Ти єси́ утвержде́ніє притека́ющих к Тебі́, Го́споди, Ти єси́ світ омраче́нних, і поє́ть Тя дух мой.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Велича́йший Макси́м, благочести́вия Христо́ви ві́ри всеї́стинно пропові́дник же і му́ченик показа́ся кро́вію.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Макси́ме блаже́нне, ти поще́нієм бил єси́ боголі́пноє любому́дрія і чи́стоє жили́ще.","Ізлія́ язи́к твой реку́ Христо́вих уче́ній благоче́стне, Макси́ме всеблаже́нне, прему́дрости пита́тель.","Богородичен: Да стезю́, Влади́ко, ко святи́ні веду́щую, пока́жеши нам, во утро́бу всесвяту́ю всели́лся єси́."]},{"h":"Кондак, глас 8","ps":["Тро́йці рачи́теля і вели́каго Макси́ма, науча́юща я́сно ві́рі Боже́ственній, є́же сла́вити Христа́, во дву єстества́х, во́лях же і ді́йствах су́ща, в пі́сніх досто́йних, ві́рнії, почти́м, взива́юще: ра́дуйся, пропові́дниче ві́ри."]},{"h":"Сідален, глас 5","ps":["Гоне́нія претерпі́в за ві́ру, отгна́л єси́, о́тче, вся́ку є́ресь, отсі́чен же с руко́ю язи́к, Макси́ме, іспові́данія благолі́пний от руки́ Творця́ прия́л єси́ віне́ць, блаже́нне. Єго́же ни́ні непреста́нно моли́ поми́ловатися душа́м на́шим.","Богородичен: По Бо́зі в Твой, Богоро́дице, прибі́г смире́нний покро́в боже́ственний, припа́дая, молю́ся: поми́луй, Пречи́стая, я́ко превзидо́ша главу́ мою́ гріси́, і бою́ся, Влади́чице, мук, і трепе́щу. Моле́ніє сотвори́, Чи́стая, к Си́ну Твоєму́ от сих ізба́вити м'я.","Хрестобогородичен: Із Безнача́льнаго Отця́ рожде́ннаго, напослі́док Тя пло́тію Ро́ждшая, на Кресті́ ви́сяща зря́щи, Христе́, — уви́ Мні, любе́знійший Ісу́се! — вопія́ше, — ка́ко сла́вимий я́ко Бог от а́нгел, от беззако́нних ни́ні челові́ков, Си́не, хотя́, распина́єшися? Пою́ Тя, Долготерпіли́ве."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Земноро́дних тя почита́ють, і небе́сних чи́ни чудя́ться, любо́вію бо му́дрости показа́лся єси́, о́тче, я́ко безпло́тен.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Су́ров у́бо мучи́тель, но терпі́ніє твоє́ непрекло́нно, тім ти у́бо ублажи́лся єси́, вселука́вий же ізве́ржеся.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Состра́ждеть тебі́, Макси́ме, ученико́в дво́їця преблаже́нная, твої́м страда́нієм приобщи́вшеся, ті́мже і по́честей ра́вно получи́ша.","Тече́нієм твоєя́ кро́ве напая́єма, Це́рков Христо́ва прозяба́єть оте́чеськаго преда́нія Боже́ственноє сі́м'я твої́м уче́нієм, преподо́бне.","Богородичен: Ізба́вльшеся Рождество́м Твої́м гріхо́внаго до́лга, Всенепоро́чная, ра́достноє пі́ніє возсила́єм Тебе́, Богоневі́сто."]},{"h":"Пісня 5","ps":["Ірмос: У́тренююще, вопіє́м Ті: Го́споди, спаси́ ни, Ти бо єси́ Бог наш, ра́зві Тебе́, іно́го не ві́ми.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Ра́зум земноро́дних собра́в і небе́сних, впра́вду филосо́ф імену́ється Макси́м.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Прему́дрости безмі́рним жела́нієм Христа́ твоєго́ подо́бник ізря́днійший яви́лся єси́, сла́вний Макси́ме.","Гні́вом ізгна́н бил єси́ мучи́теля, обрі́л же єси́, блаже́нне, Ісу́са утіше́ніє.","Богородичен: Тя Богоро́дицю неві́дущії, Богома́ти, Сві́та да не у́зрять, ро́ждшагося із Тебе́, Пречи́стая."]},{"h":"Пісня 6","ps":["Ірмос: Ри́зу мні пода́ждь сві́тлу, одія́йся сві́том, я́ко ри́зою, многоми́лостиве Христе́ Бо́же наш.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Непреста́нно прино́сиши Бо́гу, богому́дре, мольбу́, душе́вних же і тіле́сних страсте́й і тлі́нія м'я ізба́вити.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Ізсуши́ся єресе́й істо́чник му́тний весь, сла́вне Макси́ме, загражда́єм шу́мом язи́ка твоєго́.","Очи́сти м'я, Єди́не Бла́же, і істо́чник благода́ті, Христе́, се́рдцю моєму́ Твоєго́ преподо́бнаго моли́твами істочи́.","Богородичен: Красні́йшій па́че всіх челові́к Син Твой, Всечи́стая, добро́тою Божества́, а́ще і плоть нас ра́ди бисть."]},{"h":"Кондак, глас 6","ps":["Світ Трисія́нний, все́льшійся в ду́шу твою́, сосу́д ізбра́н показа́ тя, всеблаже́нне, явля́юща Боже́ственная конце́м, неудобопости́жних разумі́ній ти сказу́яй, блаже́нне, і Тро́йцю всім, Макси́ме, возпропові́дуяй я́сно, Пресу́щную, Безнача́льную."]},{"h":"Ікос","ps":["Подража́тель яви́вся Спа́сових страсте́й і Того́ в душі́ твоє́й імі́я, всеблаже́нне, восхожде́нія в се́рдці твоє́м возложи́л єси́, пребога́те. Той же тебі́ подаде́ благода́ть с небесе́, сопроти́вил бо ся єси́ мучи́телем, му́дре, му́жеськи, Безнача́льную, і Боже́ственную, і Єдиносу́щную Тро́йцю пропові́дуя і облича́я злосла́вния і богобо́рния. Безчи́сленния претерпі́л єси́ напа́сти, всехва́льне, язи́ка отрі́заніє богосло́внаго, преподо́бне, і твоєя́ руки́ вку́пі. Не преста́л же єси́ ти, со дерзнове́нієм глаго́ля і утвержда́я ві́рния боже́ственними твої́ми уче́нії, Тро́йцю всім лю́дем пропові́дуя я́сно, Пресу́щную, Безнача́льную."]},{"h":"Пісня 7","ps":["Ірмос: От Іуде́ї доше́дше, о́троци, во Вавило́ні іногда́, ві́рою Тро́йчеською пла́мень пе́щний попра́ша, пою́ще: отце́в Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Єди́но єстество́ Тро́йці, єди́но хоті́ніє рекл єси́, єди́но ді́йство, Бо́га же, вопло́щшагося во двою́ єстеству́, хоті́нію же і ді́йству пропові́дал єси́. Отце́в на́ших Бо́же, благослове́н єси́.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Не во́лі дві разділя́ємия ра́зума проти́вностію, ка́чеством же па́че пропові́дал єси́, о́тче, єсте́ственним ра́знствующия. Отце́в на́ших Бо́же, благослове́н єси́.","Столп правосла́вія боже́ственная твоя́ словеса́, о́тче, держа́ще, Єди́наго от Тро́йці во двух существа́х і во́лях почита́єм. Отце́в на́ших Бо́же, благослове́н єси́.","Богородичен: Ю́наго нося́щи Младе́нця, пре́жде всіх віко́в Бо́га, Всенепоро́чная, із Тебе́ вопло́щшагося, не преста́й моля́щи спасти́ пою́щия: отце́в на́ших Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Побіди́телі мучи́теля і пла́мене благода́тію Твоє́ю би́вше, за́повідем Твої́м зіло́ приліжа́ще, о́троци вопія́ху: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Весьма́ возлюби́в Превозлюби́вшаго род челові́чеський, крест Твой взял єси́ і Тому́, блаже́нне, сраспя́лся єси́, — благослові́те, — поя́, — діла́ Госпо́дня, Го́спода.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Устрани́вся вся́кия сла́сти, блаже́нне, смертоно́сния, тебі́ соді́лал єси́ всего́ нескве́рно зерца́ло боже́ственноє, поя́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Живоно́сну зарю́ от Єди́наго Божества́ Триіпоста́снаго приє́м, яви́лся єси́ су́щим во тьмі со́лнце заблу́ждшим, — благослові́те, — поя́, — вся діла́ Госпо́дня, Го́спода.","Богородичен: Жи́зні Тя Ма́тер і Бо́га Роди́тельницю позна́вше, правосла́вною ві́рою всі блажи́м, Богороди́тельнице, благосло́в'яще ку́пно Рождество́ Твоє́, Чи́стая, і превознося́ще во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Проявле́нноє на горі́ законополо́жнику во огні́ і купині́, Рождество́ Присноді́ви, в на́ше ві́рних спасе́ніє, пі́сньми немо́лчними велича́єм.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Єще́ твоя́, я́ко А́велева, кров і во ві́ки богодохнове́нния догма́ти гла́сом я́сним Христо́ві Це́ркві пропові́дуєть, Макси́ме всеблаже́нне і превели́кий.","Приспів: Преподо́бне о́тче Макси́ме, моли́ Бо́га о нас.","Отсіче́ся рука́, пи́шеть же боже́ственним пе́рстом, я́ко тро́стію і черни́лом, отрі́занним язи́ком і твоє́ю кро́вію честно́ю ві́ру в сердця́х правосла́вную.","Стал єси́ пред престо́лом Боже́ственним с му́ченики, ї́хже ре́вности і ві́ри приобщи́лся єси́, о́тче, і нас усво́й Влади́ці і твоя́ подража́телі соді́лай.","Богородичен: Ти єси́, Богоро́дице, ору́жіє на́ше і стіна́, Ти єси́ заступле́ніє к Тебі́ прибіга́ющих, Тя і ни́ні на моли́тву предлага́єм, да ізба́вимся от враго́в на́ших."]},{"h":"Світилен","ps":["Труба́ яви́лся єси́ прему́дрости, благогла́сним язи́ком твої́м проти́вних ужаса́я полки́, Макси́ме, світ мона́шествующих, ті́мже, твої́ми пита́ющеся словеси́, ра́зум познава́єм су́щих.","Богородичен: Світ ми́сленнаго весе́лія возсія́ла єси́ в ми́рі, Богороди́тельнице Ді́во, Ізба́вителя і Влади́ку, ті́мже помоли́ся душі́ моєя́ зі́ниці просвіти́ти сві́том сві́тлости Боже́ственния."]}],"notes":[]},{"u":"Канон великомученику Феодору Стратилату","e":"Canon to the Great Martyr Theodore Stratelates","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Мо́ря чермну́ю пучи́ну невла́жними стопа́ми дре́вній пішеше́ствовав Ізра́їль, крестообра́зними Моїсе́йовима рука́ма Амали́кову си́лу в пусти́ні побіди́л єсть.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Му́ченик, я́ві світлостьми́ украша́єм, Добротво́рцю предстої́ши Христу́, от Него́ удобря́єм, я́ко даро́в тезоімени́ть боже́ственних, му́чениче Фео́доре.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Боже́ственними вооружи́вся, Фео́доре, ору́жії ві́ри, вра́жия ссікл єси́ тве́рдо душетлі́нния полки́ і, побіди́тель бив, с му́ченики вінча́лся єси́.","Сві́тлоє твоєя́ душі́ хра́брство показу́я злочести́вому, богому́дре, царю́, прему́дростію слове́с твої́х і благода́тію діл, сего́ посрами́л єси́, Фео́доре.","Богородичен: Без сі́мене О́тчею во́лею от Боже́ственнаго Ду́ха Бо́жия зачала́ єси́ Си́на і пло́тію родила́ єси́, І́же із Отця́ без ма́тере, нас же ра́ди із Тебе́ без отця́."]},{"h":"Пісня 3","ps":["Ірмос: Весели́ться о Тебі́ Це́рков Твоя́, Христе́, зову́щи: Ти моя́ крі́пость, Го́споди, і прибі́жище, і утвержде́ніє.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Ополче́ніє злочести́воє, я́ко воєво́да си́лен, побіди́л єси́ і стропти́ваго змі́я вся хи́трости попра́л єси́.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Я́ко усе́рден душе́ю, умишле́нієм благочести́вим, сла́вне, злочести́вих погуби́л єси́ прелюбоді́йственная чти́лища.","Крі́постію по́мисла лю́тих наноше́нія претерпі́л єси́, животво́рній ме́ртвости Подвигополо́жника подо́б'яся.","Богородичен: Ти єди́на, су́щим на землі́, па́че єстества́, благи́х Хода́тайця, Ма́ти Бо́жия била́ єси́. Ті́мже Ті, ра́дуйся, вопіє́м."]},{"h":"Сідален, глас 8","ps":["Боже́ственноє всеору́жіє восприї́м і і́дольськую лесть низложи́в, а́нгели возста́вил єси́ восхвали́ти по́двиги твоя́, і́бо, боже́ственною любо́вію ум распали́в, на о́гненную смерть до́блественно дерзну́л єси́. Ті́мже тезоімени́тно прося́щим тя дає́ши боже́ственная дарова́нія, страстоте́рпче Фео́доре. Сего́ ра́ди вопіє́м ті: моли́ Христа́ Бо́га гріхо́в оставле́ніє пода́ти чту́щим любо́вію па́м'ять твою́.","Слава, і нині: В напа́сти многоплете́нния впад от враг ви́димих і неви́димих, бу́рею одержи́м безчи́сленних согріше́ній мої́х, і я́ко к те́плому заступле́нію і покро́ву моєму́, Чи́стая, ко приста́нищу притека́ю Твоєя́ бла́гости. Ті́мже, Пречи́стая, із Тебе́ воплоще́нному безсі́менно моли́ся прилі́жно о всіх рабі́х Твої́х, непреста́нно моля́щих Ті ся, Богоро́дице Пречи́стая, моля́щи Єго́ при́сно согріше́ній оставле́ніє дарова́ти воспіва́ющим досто́йно сла́ву Твою́.","Хрестобогородичен: Ді́ва і Ма́ти Ісу́сова, на дре́ві зря́щи Творця́, стеня́ше, слезя́щи, і лю́ті уязвля́шеся, ду́шу і ті́ло растерза́ющи, бію́щися, і к Нему́ вопію́щи го́рко, і взива́ющи: уви́ Мні, о Си́ні Мой! Ка́ко претерплю́ страсть Твою́, гво́здіє і копіє́, Я́же без болі́зні Тя ро́ждши? Но потщи́ся воста́ти, і ви́діти Тя, Си́не Мой і Бо́же, і от рида́нія преста́ти і болі́зні, і пою́щії Твоя́ стра́сті согріше́ній разріше́ніє при́ймуть."]},{"h":"Пісня 4","ps":["Ірмос: Вознесе́на Тя ви́дівши Це́рков на Кресті́, Со́лнце Пра́ведноє, ста в чи́ні своє́м, досто́йно взива́ющи: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Уязви́л єси́ змі́я, уязви́ти тя хотя́щаго, і терпіли́вими сопротивле́нії му́ченик яви́лся єси́, поя́ прилі́жно тя Укрі́пльшему: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Ізнури́в плоть мно́гими ра́нами, по́мисл непрекло́нен поста́вил єси́, треблаже́нне, поя́ усе́рдно тя Укрі́пльшему: сла́ва си́лі Твоє́й, Го́споди.","Украси́лся єси́ страда́ньми Влади́ки, твоя́ честна́я страда́нія, прему́дре, совоку́пль, і сподо́бился єси́ Того́ сві́тлости і жела́ємия красоти́.","Богородичен: Неіскусобра́чно родила́ єси́, о Ді́во, і по рождестві́ яви́лася єси́ ді́вствующи па́ки. Ті́мже немо́лчними гла́си, є́же ра́дуйся, Тебе́, Влади́чице, ві́рою несумні́нною взива́єм."]},{"h":"Пісня 5","ps":["Ірмос: Ти, Го́споди, мой Світ, в мир прише́л єси́, Світ Святи́й, обраща́яй із мра́чна неві́дінія ві́рою воспіва́ющія Тя.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Кропле́нієм плотськи́х крове́й уста́вил єси́ де́монськую на па́губу приноси́мую кров, непобіди́ме Фео́доре.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","О, нра́ва благочести́ва! О, до́блественна ра́зума! О, ві́ри теплі́йшия честна́го страстоте́рпця, є́юже Бо́га получи́!","Ум імі́я, сві́том Бо́жиїм осія́єм, побо́рника зло́би омрачи́л єси́, змі́я, богоно́се Фео́доре.","Богородичен: Тя ору́жіє непобіди́моє на враги́ предлага́єм, Тя утвержде́ніє і наде́жду на́шего спасе́нія, Богоневі́сто, стяжа́хом."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею кро́вію.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Побіди́л єси́ усе́рдієм де́рзостним низлага́ющих, на кресті́ просте́рт і гвоздьми́ пробода́єм, блаже́нне, ізобража́я спаси́тельную страсть Зижди́теля.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Зако́нно стра́ждущему, Христо́с тебі́ явля́ється, в темни́ці затворе́ну, воздвиза́я я́ко Подвигополо́жник к подвиго́м на враги́ боре́нія, пресла́вне.","Же́ртву чи́сту, і свя́ту, і непоро́чну тебе́ ра́ди во́лею Себі́ же́ртву прине́сшему, приве́л єси́ себе́, страстоте́рпче Фео́доре.","Богородичен: О, чу́до, всіх чуде́с нові́йшеє! Я́ко Ді́ва, во утро́бі вся Содержа́щаго неіскусому́жно заче́нши, не тісновмісти́."]},{"h":"Кондак, глас 2","ps":["Му́жеством душі́ во ві́ру оболки́йся і глаго́л Бо́жий, а́ки копіє́, в ру́ку взем, врага́ побіди́л єси́, му́чеников преве́лій Фео́доре, с ни́ми Христу́ Бо́гу моля́ся не преста́й о всіх нас."]},{"h":"Ікос","ps":["Страда́льцев пресві́тлую добро́ту, прийді́те всі, пі́сненними вінці́, ві́рнії, Фео́дора вінча́єм: дар бо Бо́жий вели́к ми́ру яви́ся сія́ньми чуде́с. Врага́ бо побі́ждь велія́ра страда́нії честни́ми, одождя́єть вмі́сто кро́вних ка́плей ісціле́ній то́ки, с си́ми у́бо всі́ми ра́дується Христу́ і дає́ть мир неоскуде́н. Тім вопіє́м єму́: моли́ непреста́нно о всіх нас."]},{"h":"Пісня 7","ps":["Ірмос: В пещі́ авраа́мстії о́троци перси́дстій, любо́вію благоче́стія па́че, не́жели пла́менем, опаля́ємі, взива́ху: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","В пещі́ твої́х подвиго́в, му́чениче сла́вне, вещ злоче́стія попали́л єси́ і світи́ло благоче́стія, поя́, бил єси́: благослове́н єси́ в хра́мі сла́ви Твоєя́, Го́споди.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Я́ко воєво́да, я́ко сми́слен і тре́звеник ді́лом, царя́ несми́сленна і злочести́ва премо́гл єси́ і показа́л єси́ сего́ некрі́пка, укріпи́вся си́лою духо́вною.","Зако́н побіжда́ється похвала́ми вели́чества твоєго́: ти бо пресві́тлими просія́л єси́ облиста́нії муче́нія, Влади́ці твоєму́ вопія́, Фео́доре: благослове́нна держа́ва Твоєго́ влади́чества.","Богородичен: Ви́шняго освяще́нноє боже́ственноє селе́ніє, ра́дуйся, Тобо́ю бо даде́ся ра́дость, Богоро́дице, зову́щим: благослове́нна Ти в жена́х єси́, Всенепоро́чная Влади́чице."]},{"h":"Пісня 8","ps":["Ірмос: Ру́ці распросте́р, Данії́л, львов зія́нія в ро́ві затче́; о́гненную же си́лу угаси́ша, доброді́телію препоя́савшеся, благоче́стія рачи́тели, о́троци, взива́юще: благослові́те, вся діла́ Госпо́дня, Го́спода.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","На Тя упова́в, мене́ ра́ди Крест і смерть претерпі́вшаго, на крест воздвиго́хся, Влади́ко, і уязвля́єм стріля́ньми, і лю́тим прикаса́яся ра́нам, Го́споди, — вопія́л єси́, му́чениче, стражда́, доблему́дренне Фео́доре.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Приве́л єси́ же́ртву чи́сту тебі́ Зижди́телю твоєму́, ра́дуяся, Фео́доре, і отлучи́вся, сла́вне, к Ца́рству небе́сному, с му́ченики свяще́нно взива́я всегда́: благослові́те, вся діла́ Госпо́дня, Го́спода.","Я́ко крин, я́ко ши́пок разу́мний, воня́ми страда́ній твої́х благоуха́єши нас, отгоня́ благода́тію всегда́ злосмра́діє страсте́й на́ших і понужда́я вопи́ти благово́нною душе́ю: благослові́те, вся діла́ Госпо́дня, Го́спода.","Богородичен: Ти єди́на во всіх роді́х, Ді́во Пречи́стая, Ма́ти яви́лася єси́ Бо́жия, Ти Божества́ била́ єси́ жили́ще, Всенепоро́чная, не опа́льшися огне́м непристу́пнаго Сві́та. Ті́мже всі Тя благослови́м, Марі́є Богоневі́сто."]},{"h":"Пісня 9","ps":["Ірмос: Ка́мень нерукосі́чний от несіко́мия гори́, Тебі́, Ді́во, краєуго́льний отсіче́ся — Христо́с, совокупи́вий разстоя́щаяся єстества́. Тім, веселя́щеся, Тя, Богоро́дице, велича́єм.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","Ни́ні со блаже́нними собо́ри і му́ченичеськими ли́ки, я́ко укра́шен страда́ньми, соводворя́яся і свеселя́ся, віне́ць нося́, предстої́ши Жела́ємому тебі́, Фео́доре.","Приспів: Святи́й великому́чениче Фео́доре, моли́ Бо́га о нас.","К висоті́ небе́сній взя́ться, о земни́х небре́г, і жела́ємаго тебі́ конця́ сподо́бился єси́, то са́моє соверше́ніє жела́ній, Фео́доре, восприє́м, ра́дуяся.","Іми́й к Бо́гу дерзнове́ніє, я́ко добль і мудр страда́лець, восхваля́ющим тя любо́вію согріше́ній оставле́ніє проси́, от страсте́й і скорбе́й всіх нас избавля́я.","Єди́наго Тя, безсме́ртна Сло́ва, пло́тію пострада́вша і уме́рша, му́ченик богому́дрий возжела́в, безсме́ртія Твоєго́ получи́в, на небеса́ всели́ся, к Зижди́телю всіх Всеси́льну.","Богородичен: Благослове́нную Марі́ю і Бо́жию Ма́тер Ді́ву, прийді́те всі, ві́рою і любо́вію непреста́нно восхва́лим, Єя́же ра́ди обрі́тше ві́чноє ра́дованіє."]},{"h":"Світилен","ps":["Ти, красе́н добро́тою, і воєво́да благомо́щен, і сла́вний во страда́льціх во́їн, прине́слся єси́ Христу́ і ми́ру дар боже́ственний, Фео́доре, показа́лся єси́.","Слава, і нині: Держа́вним Твої́м кро́вом от враг наві́та нас, Чи́стая, Твоя́ раби́, сохраня́й вся невре́дни: Тя бо стяжа́хом єди́ну прибі́жище в ну́ждах."]}],"notes":[]}];
export default D;
